(* Machine 1RB0LE_0RC---_1RD0LA_1RE0RA_0LF1LD_1LC1RF halts from the blank tape: state B reading 1 after
   21258455156613008579829807130432544 steps (one more with the halting step), sigma 132543575383248966.
   Those two numbers come from a simulator and are not part of the theorem at the end of this file.
   Layout: small constants; a generic checker (nothing in it is machine specific); an untrusted decoder; the certificate
   (15580 rules, one LZ-compressed string, 1 MB, written by a simulator that is not trusted); the theorem.
   Print Assumptions lists only Coq's primitive integer, array and string operations. *)
From Coq Require PArray Uint63 ZArith PrimString.

Module SkInts.
Import PArray Uint63 ZArith.
Open Scope uint63_scope.
Definition i0 : int := 0.
Definition i1 : int := 1.
Definition i6 : int := 6.
Definition i10 : int := 10.
Definition i31 : int := 31.
Definition i32 : int := 32.
Definition i63 : int := 63.
Definition i5 : int := 5.
Definition i48 : int := 48.
Definition flag : int := 4611686018427387904.
Definition mask60 : int := 1152921504606846975.
Definition small : array Z :=
  [| 0%Z;1%Z;2%Z;3%Z;4%Z;5%Z;6%Z;7%Z;8%Z;9%Z;10%Z;11%Z;12%Z;13%Z;14%Z;15%Z;16%Z;17%Z;18%Z;19%Z;20%Z;21%Z;22%Z;23%Z;24%Z;25%Z;26%Z;27%Z;28%Z;29%Z;30%Z;31%Z | 0%Z : Z |].
End SkInts.

(* A reflective checker for run-length rule certificates over busycoq's TM semantics.
   A certificate is a list of rules; each rule is a statement about k-cell block run-lengths with affine counts, and is
   proved by a list of actions (block steps, chain steps, applications of earlier rules). Nothing here is machine specific. *)
From BusyCoq Require Import Individual62.
From Coq Require Import ZArith Lia List Bool Arith.
Import ListNotations.
Set Default Goal Selector "!".

Local Open Scope Z_scope.

(* ---------- affine expressions ---------- *)
Definition Aff : Type := (Z * list (nat * Z))%type.
Definition Val := nat -> Z.

Fixpoint lsum (rho : Val) (l : list (nat * Z)) : Z :=
  match l with
  | [] => 0
  | (v, a) :: t => a * rho v + lsum rho t
  end.

Definition aeval (rho : Val) (e : Aff) : Z := fst e + lsum rho (snd e).

Fixpoint ladd1 (v : nat) (c : Z) (l : list (nat * Z)) : list (nat * Z) :=
  match l with
  | [] => if Z.eqb c 0 then [] else [(v, c)]
  | (w, d) :: t =>
    if Nat.eqb v w then (if Z.eqb (c + d) 0 then t else (w, c + d) :: t)
    else if Nat.ltb v w then (if Z.eqb c 0 then l else (v, c) :: l)
    else (w, d) :: ladd1 v c t
  end.

Lemma lsum_ladd1 rho v c l : lsum rho (ladd1 v c l) = c * rho v + lsum rho l.
Proof.
  induction l as [| [w d] t IH]; cbn [ladd1 lsum].
  - destruct (Z.eqb_spec c 0); subst; cbn; lia.
  - destruct (Nat.eqb_spec v w).
    + subst v. destruct (Z.eqb_spec (c + d) 0).
      * assert (d = - c) by lia. subst d. lia.
      * cbn [lsum]. lia.
    + destruct (Nat.ltb_spec v w).
      * destruct (Z.eqb_spec c 0); subst; cbn [lsum]; lia.
      * cbn [lsum]. rewrite IH. lia.
Qed.

Definition ladd (a b : list (nat * Z)) : list (nat * Z) :=
  fold_right (fun p acc => ladd1 (fst p) (snd p) acc) b a.

Lemma lsum_ladd rho a b : lsum rho (ladd a b) = lsum rho a + lsum rho b.
Proof.
  induction a as [| [v c] t IH]; cbn [ladd fold_right lsum fst snd]; [lia |].
  unfold ladd in IH. rewrite lsum_ladd1, IH. lia.
Qed.

Definition aadd (a b : Aff) : Aff := (fst a + fst b, ladd (snd a) (snd b)).
Lemma aeval_aadd rho a b : aeval rho (aadd a b) = aeval rho a + aeval rho b.
Proof. unfold aeval, aadd. cbn [fst snd]. rewrite lsum_ladd. lia. Qed.

Fixpoint lscale (s : Z) (l : list (nat * Z)) : list (nat * Z) :=
  match l with
  | [] => []
  | (v, a) :: t => (v, s * a) :: lscale s t
  end.
Lemma lsum_lscale rho s l : lsum rho (lscale s l) = s * lsum rho l.
Proof. induction l as [| [v a] t IH]; cbn [lscale lsum]; [lia | rewrite IH; lia]. Qed.

Definition ascale (s : Z) (a : Aff) : Aff :=
  if Z.eqb s 0 then (0, []) else (s * fst a, lscale s (snd a)).
Lemma aeval_ascale rho s a : aeval rho (ascale s a) = s * aeval rho a.
Proof.
  unfold ascale. destruct (Z.eqb_spec s 0).
  - subst. cbn. reflexivity.
  - unfold aeval. cbn [fst snd]. rewrite lsum_lscale. lia.
Qed.

Definition aconst (c : Z) : Aff := (c, []).
Lemma aeval_aconst rho c : aeval rho (aconst c) = c.
Proof. unfold aeval, aconst. cbn. lia. Qed.

Definition aiszero (a : Aff) : bool :=
  Z.eqb (fst a) 0 && match snd a with [] => true | _ => false end.
Lemma aiszero_spec rho a : aiszero a = true -> aeval rho a = 0.
Proof.
  unfold aiszero, aeval. destruct a as [c l]. cbn [fst snd].
  destruct (Z.eqb_spec c 0); [| discriminate]. destruct l; [| discriminate].
  intros _. cbn. lia.
Qed.

Definition aeq (a b : Aff) : bool := aiszero (aadd a (ascale (-1) b)).
Lemma aeq_spec rho a b : aeq a b = true -> aeval rho a = aeval rho b.
Proof.
  unfold aeq. intros H. apply (aiszero_spec rho) in H.
  rewrite aeval_aadd, aeval_ascale in H. lia.
Qed.

(* substitution of variables by affine expressions *)
Fixpoint lsubst (f : nat -> Aff) (l : list (nat * Z)) : Aff :=
  match l with
  | [] => (0, [])
  | (v, a) :: t => aadd (ascale a (f v)) (lsubst f t)
  end.
Definition asubst (f : nat -> Aff) (e : Aff) : Aff := aadd (aconst (fst e)) (lsubst f (snd e)).

Definition vcomp (rho : Val) (f : nat -> Aff) : Val := fun i => aeval rho (f i).

Lemma lsubst_spec rho f l : aeval rho (lsubst f l) = lsum (vcomp rho f) l.
Proof.
  induction l as [| [v a] t IH]; cbn [lsubst lsum].
  - unfold aeval. cbn. lia.
  - rewrite aeval_aadd, aeval_ascale, IH. reflexivity.
Qed.

Lemma asubst_spec rho f e : aeval rho (asubst f e) = aeval (vcomp rho f) e.
Proof.
  unfold asubst. rewrite aeval_aadd, aeval_aconst, lsubst_spec. reflexivity.
Qed.

(* guards: e >= 0 *)
Fixpoint leq (a b : list (nat * Z)) : bool :=
  match a, b with
  | [], [] => true
  | (v, x) :: a', (w, y) :: b' => Nat.eqb v w && Z.eqb x y && leq a' b'
  | _, _ => false
  end.
Lemma leq_spec a b : leq a b = true -> a = b.
Proof.
  revert b. induction a as [| [v x] a IH]; destruct b as [| [w y] b]; cbn; try discriminate; [reflexivity |].
  intros H. apply andb_prop in H. destruct H as [H H3]. apply andb_prop in H. destruct H as [H1 H2].
  apply Nat.eqb_eq in H1. apply Z.eqb_eq in H2. apply IH in H3. congruence.
Qed.

Definition impl1 (g t : Aff) : bool :=
  match snd t, snd g with
  | (_, b) :: _, (_, a) :: _ =>
    let s := Z.div a b in
    Z.ltb 0 s
      && leq (snd g) (lscale s (snd t))
      && Z.leb (fst g) (s * fst t + s - 1)
  | _, _ => false
  end.

Lemma impl1_spec rho g t : impl1 g t = true -> 0 <= aeval rho g -> 0 <= aeval rho t.
Proof.
  unfold impl1.
  destruct (snd t) as [| [v b] tt] eqn:Et; [discriminate |].
  destruct (snd g) as [| [w a] gt] eqn:Eg; [discriminate |].
  set (s := Z.div a b).
  destruct (Z.ltb_spec 0 s); [| rewrite ?andb_false_l; discriminate].
  rewrite andb_true_l.
  destruct (leq _ _) eqn:Hl; [| rewrite andb_false_l; discriminate].
  apply leq_spec in Hl. rename Hl into Heq.
  rewrite andb_true_l.
  destruct (Z.leb_spec (fst g) (s * fst t + s - 1)); [| discriminate].
  intros _ Hg.
  unfold aeval in *. rewrite Eg, Heq, lsum_lscale in Hg. rewrite Et.
  set (Q := lsum rho ((v, b) :: tt)) in *.
  nia.
Qed.

Definition impl2 (g t : Aff) : bool :=
  match snd t, snd g with
  | (_, b) :: _, (_, a) :: _ =>
    let s := Z.div b a in
    Z.ltb 0 s && leq (snd t) (lscale s (snd g)) && Z.leb (s * fst g) (fst t)
  | _, _ => false
  end.

Lemma impl2_spec rho g t : impl2 g t = true -> 0 <= aeval rho g -> 0 <= aeval rho t.
Proof.
  unfold impl2.
  destruct (snd t) as [| [v b] tt] eqn:Et; [discriminate |].
  destruct (snd g) as [| [w a] gt] eqn:Eg; [discriminate |].
  set (s := Z.div b a).
  destruct (Z.ltb_spec 0 s); [| rewrite ?andb_false_l; discriminate].
  rewrite andb_true_l.
  destruct (leq _ _) eqn:Hl; [| rewrite andb_false_l; discriminate].
  apply leq_spec in Hl. rewrite andb_true_l.
  destruct (Z.leb_spec (s * fst g) (fst t)); [| discriminate].
  intros _ Hg.
  unfold aeval in *. rewrite Et, Hl, lsum_lscale. rewrite Eg in Hg.
  set (Q := lsum rho ((w, a) :: gt)) in *.
  nia.
Qed.

Definition implied (G : list Aff) (t : Aff) : bool :=
  match snd t with
  | [] => Z.leb 0 (fst t)
  | _ => existsb (fun g => impl1 g t || impl2 g t) G
  end.

Definition holds (rho : Val) (G : list Aff) : Prop := forall g, In g G -> 0 <= aeval rho g.

Lemma implied_spec rho G t : holds rho G -> implied G t = true -> 0 <= aeval rho t.
Proof.
  intros HG. unfold implied.
  destruct (snd t) eqn:E.
  - intros H. apply Z.leb_le in H. unfold aeval. rewrite E. cbn. lia.
  - intros H. apply existsb_exists in H. destruct H as [g [Hin H]].
    apply orb_prop in H. destruct H as [H | H].
    + eapply impl1_spec; [exact H | apply HG, Hin].
    + eapply impl2_spec; [exact H | apply HG, Hin].
Qed.

(* ---------- run-length stacks ---------- *)
Definition Stk := list (list Sym * Aff).

Fixpoint sden (rho : Val) (xs : Stk) (t : side) : side :=
  match xs with
  | [] => t
  | (w, e) :: ys => w ^^ Z.to_nat (aeval rho e) *> sden rho ys t
  end.

Definition sym_eq (a b : Sym) : bool :=
  match a, b with S0, S0 | S1, S1 => true | _, _ => false end.
Lemma sym_eq_spec a b : sym_eq a b = true -> a = b.
Proof. destruct a, b; cbn; congruence. Qed.

Fixpoint weq (a b : list Sym) : bool :=
  match a, b with
  | [], [] => true
  | x :: a', y :: b' => sym_eq x y && weq a' b'
  | _, _ => false
  end.
Lemma weq_spec a b : weq a b = true -> a = b.
Proof.
  revert b. induction a as [| x a IH]; destruct b as [| y b]; cbn; try discriminate; [reflexivity |].
  intros H. apply andb_prop in H. destruct H as [H1 H2].
  apply sym_eq_spec in H1. apply IH in H2. congruence.
Qed.

Definition q_eq (a b : Q) : bool :=
  match a, b with A, A | B, B | C, C | D, D | E, E | F, F => true | _, _ => false end.
Lemma q_eq_spec a b : q_eq a b = true -> a = b.
Proof. destruct a, b; cbn; congruence. Qed.

Definition dir_eq (a b : dir) : bool :=
  match a, b with L, L | R, R => true | _, _ => false end.
Lemma dir_eq_spec a b : dir_eq a b = true -> a = b.
Proof. destruct a, b; cbn; congruence. Qed.

Definition allzero (w : list Sym) : bool := forallb (fun b => sym_eq b S0) w.

Lemma allzero_word w : allzero w = true -> w *> const S0 = const S0.
Proof.
  induction w as [| b w IH]; cbn; [reflexivity |].
  intros H. apply andb_prop in H. destruct H as [H1 H2].
  apply sym_eq_spec in H1. subst b. rewrite IH by exact H2. symmetry. apply const_unfold.
Qed.

Lemma allzero_pow w n : allzero w = true -> w ^^ n *> const S0 = const S0.
Proof.
  intros H. induction n as [| n IH]; cbn [lpow]; [reflexivity |].
  rewrite Str_app_assoc, IH. apply allzero_word, H.
Qed.

(* push a run; the merge needs both counts nonnegative *)
Definition spush (G : list Aff) (cl : bool) (w : list Sym) (e : Aff) (xs : Stk) : option Stk :=
  match xs with
  | [] => if cl && allzero w then Some [] else Some [(w, e)]
  | (w0, e0) :: ys =>
    if weq w w0 then
      if implied G e && implied G e0 then Some ((w, aadd e e0) :: ys) else None
    else Some ((w, e) :: xs)
  end.

Lemma spush_spec rho G cl w e xs ys t :
  holds rho G -> (cl = true -> t = const S0) -> spush G cl w e xs = Some ys ->
  sden rho ys t = w ^^ Z.to_nat (aeval rho e) *> sden rho xs t.
Proof.
  intros HG Ht H. destruct xs as [| [w0 e0] zs]; cbn [spush] in H.
  - destruct (cl && allzero w) eqn:E.
    + apply andb_prop in E. destruct E as [E1 E2]. inversion H; subst ys.
      cbn [sden]. rewrite (Ht E1). rewrite allzero_pow by exact E2. reflexivity.
    + inversion H; subst ys. reflexivity.
  - destruct (weq w w0) eqn:Ew.
    + apply weq_spec in Ew. subst w0.
      destruct (implied G e && implied G e0) eqn:E2; [| discriminate].
      apply andb_prop in E2. destruct E2 as [E1 E2].
      apply (implied_spec rho) in E1; [| exact HG]. apply (implied_spec rho) in E2; [| exact HG].
      inversion H; subst ys. cbn [sden]. rewrite aeval_aadd, Z2Nat.inj_add by lia.
      rewrite lpow_add, Str_app_assoc. reflexivity.
    + inversion H; subst ys. reflexivity.
Qed.

Fixpoint spushes (G : list Aff) (cl : bool) (xs : Stk) (ys : Stk) : option Stk :=
  match xs with
  | [] => Some ys
  | (w, e) :: t =>
    match spushes G cl t ys with
    | None => None
    | Some zs => spush G cl w e zs
    end
  end.

Lemma spushes_spec rho G cl xs ys zs t :
  holds rho G -> (cl = true -> t = const S0) -> spushes G cl xs ys = Some zs ->
  sden rho zs t = sden rho xs (sden rho ys t).
Proof.
  intros HG Ht. revert zs. induction xs as [| [w e] u IH]; intros zs H; cbn [spushes] in H.
  - inversion H; subst zs. reflexivity.
  - destruct (spushes G cl u ys) as [vs |] eqn:E; [| discriminate].
    erewrite spush_spec; [| exact HG | exact Ht | exact H].
    rewrite (IH vs eq_refl). reflexivity.
Qed.

(* pop one block off a run with count e >= 1 *)
Definition dec1 (w : list Sym) (e : Aff) (ys : Stk) : Stk :=
  let e' := aadd e (aconst (-1)) in
  if aiszero e' then ys else (w, e') :: ys.

Lemma dec1_spec rho w e ys t :
  1 <= aeval rho e ->
  sden rho ((w, e) :: ys) t = w *> sden rho (dec1 w e ys) t.
Proof.
  intros H. unfold dec1. cbn [sden].
  assert (Hto : Z.to_nat (aeval rho e) = S (Z.to_nat (aeval rho (aadd e (aconst (-1)))))).
  { rewrite aeval_aadd, aeval_aconst. lia. }
  rewrite Hto. cbn [lpow]. rewrite Str_app_assoc.
  destruct (aiszero (aadd e (aconst (-1)))) eqn:E.
  - apply (aiszero_spec rho) in E. rewrite E. cbn. reflexivity.
  - cbn [sden]. reflexivity.
Qed.

(* ---------- local run inside a block ---------- *)
Section Run.
Variable tm : TM.
Variable kk : nat.
Variable fuel : nat.

Notation "c -->+ c'" := (c -[ tm ]->+ c') (at level 40).
Notation "c -->* c'" := (c -[ tm ]->* c') (at level 40).

Definition cfg (q : Q) (d : dir) (l r : side) : Q * tape :=
  match d with
  | L => l <{{q}} r
  | R => l {{q}}> r
  end.

Fixpoint zrun (n : nat) (q : Q) (d : dir) (ls rs : list Sym) : option (Q * dir * list Sym * list Sym) :=
  match n with
  | O => None
  | S n' =>
    match d with
    | L =>
      match ls with
      | [] => Some (q, L, [], rs)
      | b :: ls' =>
        match tm (q, b) with
        | None => None
        | Some (s, L, q') => zrun n' q' L ls' (s :: rs)
        | Some (s, R, q') => zrun n' q' R (s :: ls') rs
        end
      end
    | R =>
      match rs with
      | [] => Some (q, R, ls, [])
      | b :: rs' =>
        match tm (q, b) with
        | None => None
        | Some (s, L, q') => zrun n' q' L ls (s :: rs')
        | Some (s, R, q') => zrun n' q' R (s :: ls) rs'
        end
      end
    end
  end.

Lemma step_at_L q b s d' q' l r :
  tm (q, b) = Some (s, d', q') ->
  cfg q L (b >> l) r -[ tm ]-> cfg q' d' (match d' with L => l | R => s >> l end) (match d' with L => s >> r | R => r end).
Proof.
  intros H. destruct d'; cbn [cfg tl hd].
  - apply (step_left (l := l) (r := r)) in H. exact H.
  - apply (step_right (l := l) (r := r)) in H. exact H.
Qed.

Lemma step_at_R q b s d' q' l r :
  tm (q, b) = Some (s, d', q') ->
  cfg q R l (b >> r) -[ tm ]-> cfg q' d' (match d' with L => l | R => s >> l end) (match d' with L => s >> r | R => r end).
Proof.
  intros H. destruct d'; cbn [cfg tl hd].
  - apply (step_left (l := l) (r := r)) in H. exact H.
  - apply (step_right (l := l) (r := r)) in H. exact H.
Qed.

Lemma zrun_spec n q d ls rs q' d' ls' rs' l r :
  zrun n q d ls rs = Some (q', d', ls', rs') ->
  cfg q d (ls *> l) (rs *> r) -->* cfg q' d' (ls' *> l) (rs' *> r).
Proof.
  revert q d ls rs. induction n as [| n IH]; intros q d ls rs H; cbn [zrun] in H; [discriminate |].
  destruct d.
  - destruct ls as [| b ls0].
    + inversion H; subst. apply evstep_refl.
    + destruct (tm (q, b)) as [[[s []] q1] |] eqn:E; [| | discriminate].
      * eapply evstep_step; [apply (step_at_L q b s L q1 (ls0 *> l) (rs *> r) E) |].
        exact (IH _ _ _ _ H).
      * eapply evstep_step; [apply (step_at_L q b s R q1 (ls0 *> l) (rs *> r) E) |].
        exact (IH _ _ _ _ H).
  - destruct rs as [| b rs0].
    + inversion H; subst. apply evstep_refl.
    + destruct (tm (q, b)) as [[[s []] q1] |] eqn:E; [| | discriminate].
      * eapply evstep_step; [apply (step_at_R q b s L q1 (ls *> l) (rs0 *> r) E) |].
        exact (IH _ _ _ _ H).
      * eapply evstep_step; [apply (step_at_R q b s R q1 (ls *> l) (rs0 *> r) E) |].
        exact (IH _ _ _ _ H).
Qed.

(* with a cell in front of the head there is at least one step *)
Lemma zrun_prog n q d ls rs q' d' ls' rs' l r :
  match d with L => ls <> [] | R => rs <> [] end ->
  zrun n q d ls rs = Some (q', d', ls', rs') ->
  cfg q d (ls *> l) (rs *> r) -->+ cfg q' d' (ls' *> l) (rs' *> r).
Proof.
  intros Hne H. destruct n as [| n]; cbn [zrun] in H; [discriminate |].
  destruct d.
  - destruct ls as [| b ls0]; [congruence |].
    destruct (tm (q, b)) as [[[s []] q1] |] eqn:E; [| | discriminate].
    + eapply progress_intro; [apply (step_at_L q b s L q1 (ls0 *> l) (rs *> r) E) |].
      exact (zrun_spec n q1 L ls0 (s :: rs) _ _ _ _ l r H).
    + eapply progress_intro; [apply (step_at_L q b s R q1 (ls0 *> l) (rs *> r) E) |].
      exact (zrun_spec n q1 R (s :: ls0) rs _ _ _ _ l r H).
  - destruct rs as [| b rs0]; [congruence |].
    destruct (tm (q, b)) as [[[s []] q1] |] eqn:E; [| | discriminate].
    + eapply progress_intro; [apply (step_at_R q b s L q1 (ls *> l) (rs0 *> r) E) |].
      exact (zrun_spec n q1 L ls (s :: rs0) _ _ _ _ l r H).
    + eapply progress_intro; [apply (step_at_R q b s R q1 (ls *> l) (rs0 *> r) E) |].
      exact (zrun_spec n q1 R (s :: ls) rs0 _ _ _ _ l r H).
Qed.

(* head moving right over a block w: result (q', d', w') with w' the block behind the head *)
Definition brun_R (q : Q) (w : list Sym) : option (Q * dir * list Sym) :=
  match w with
  | [] => None
  | _ =>
    match zrun fuel q R [] w with
    | Some (q', R, ls', []) => Some (q', R, ls')
    | Some (q', L, [], rs') => Some (q', L, rs')
    | _ => None
    end
  end.

Definition brun_L (q : Q) (w : list Sym) : option (Q * dir * list Sym) :=
  match w with
  | [] => None
  | _ =>
    match zrun fuel q L w [] with
    | Some (q', R, ls', []) => Some (q', R, ls')
    | Some (q', L, [], rs') => Some (q', L, rs')
    | _ => None
    end
  end.

Lemma brun_R_spec q w q' d' w' l r :
  brun_R q w = Some (q', d', w') ->
  l {{q}}> (w *> r) -->+ cfg q' d' (match d' with L => l | R => w' *> l end) (match d' with L => w' *> r | R => r end).
Proof.
  unfold brun_R. destruct w as [| b w0]; [discriminate |].
  destruct (zrun fuel q R [] (b :: w0)) as [[[[q1 d1] ls1] rs1] |] eqn:E; [| discriminate].
  pose proof (zrun_prog fuel q R [] (b :: w0) q1 d1 ls1 rs1 l r ltac:(discriminate) E) as Hp.
  destruct d1.
  - destruct ls1; [| discriminate]. intros H. inversion H; subst. exact Hp.
  - destruct rs1; [| discriminate]. intros H. inversion H; subst. exact Hp.
Qed.

Lemma brun_L_spec q w q' d' w' l r :
  brun_L q w = Some (q', d', w') ->
  (w *> l) <{{q}} r -->+ cfg q' d' (match d' with L => l | R => w' *> l end) (match d' with L => w' *> r | R => r end).
Proof.
  unfold brun_L. destruct w as [| b w0]; [discriminate |].
  destruct (zrun fuel q L (b :: w0) []) as [[[[q1 d1] ls1] rs1] |] eqn:E; [| discriminate].
  pose proof (zrun_prog fuel q L (b :: w0) [] q1 d1 ls1 rs1 l r ltac:(discriminate) E) as Hp.
  destruct d1.
  - destruct ls1; [| discriminate]. intros H. inversion H; subst. exact Hp.
  - destruct rs1; [| discriminate]. intros H. inversion H; subst. exact Hp.
Qed.

(* chain lemmas *)
Lemma chain_R q w w' n l r :
  brun_R q w = Some (q, R, w') ->
  l {{q}}> (w ^^ S n *> r) -->+ (w' ^^ S n *> l) {{q}}> r.
Proof.
  intros H. revert l. induction n as [| n IH]; intros l.
  - cbn [lpow]. rewrite !app_nil_r. exact (brun_R_spec _ _ _ _ _ l r H).
  - change (w ^^ S (S n)) with (w ++ w ^^ S n). rewrite Str_app_assoc.
    eapply progress_trans; [exact (brun_R_spec q w q R w' l _ H) |].
    cbn [cfg]. specialize (IH (w' *> l)).
    replace (w' ^^ S (S n) *> l) with (w' ^^ S n *> w' *> l); [exact IH |].
    rewrite lpow_shift'. change (w' ^^ S (S n)) with (w' ++ w' ^^ S n). rewrite Str_app_assoc. reflexivity.
Qed.

Lemma chain_L q w w' n l r :
  brun_L q w = Some (q, L, w') ->
  (w ^^ S n *> l) <{{q}} r -->+ l <{{q}} (w' ^^ S n *> r).
Proof.
  intros H. revert r. induction n as [| n IH]; intros r.
  - cbn [lpow]. rewrite !app_nil_r. exact (brun_L_spec _ _ _ _ _ l r H).
  - change (w ^^ S (S n)) with (w ++ w ^^ S n). rewrite Str_app_assoc.
    eapply progress_trans; [exact (brun_L_spec q w q L w' _ r H) |].
    cbn [cfg]. specialize (IH (w' *> r)).
    replace (w' ^^ S (S n) *> r) with (w' ^^ S n *> w' *> r); [exact IH |].
    rewrite lpow_shift'. change (w' ^^ S (S n)) with (w' ++ w' ^^ S n). rewrite Str_app_assoc. reflexivity.
Qed.

(* ---------- configurations ---------- *)
Record Cfg := mkC { cq : Q; cd : dir; cl : Stk; cr : Stk }.

Definition den (rho : Val) (tl tr : side) (c : Cfg) : Q * tape :=
  cfg (cq c) (cd c) (sden rho (cl c) tl) (sden rho (cr c) tr).

Fixpoint zeros (n : nat) : list Sym :=
  match n with
  | O => []
  | S n' => S0 :: zeros n'
  end.

Lemma zeros_word n : zeros n *> const S0 = const S0.
Proof.
  induction n as [| n IH]; cbn; [reflexivity |].
  rewrite IH. symmetry. apply const_unfold.
Qed.

Definition cone : Aff := aconst 1.

(* a block step, or a chain step when the block returns the same state and direction *)
Definition exec_step (G : list Aff) (cL cR : bool) (c : Cfg) : option Cfg :=
  match c with
  | mkC q R ls rs =>
    match rs with
    | [] =>
      if cR then
        match brun_R q (zeros kk) with
        | Some (q', R, w') =>
          if q_eq q' q then None else
          match spush G cL w' cone ls with
          | Some ls' => Some (mkC q' R ls' [])
          | None => None
          end
        | Some (q', L, w') =>
          match spush G cR w' cone [] with
          | Some rs' => Some (mkC q' L ls rs')
          | None => None
          end
        | None => None
        end
      else None
    | (w, e) :: ys =>
      if implied G (aadd e (aconst (-1))) then
        match brun_R q w with
        | Some (q', R, w') =>
          if q_eq q' q then
            match spush G cL w' e ls with
            | Some ls' => Some (mkC q R ls' ys)
            | None => None
            end
          else
            match spush G cL w' cone ls with
            | Some ls' => Some (mkC q' R ls' (dec1 w e ys))
            | None => None
            end
        | Some (q', L, w') =>
          match spush G cR w' cone (dec1 w e ys) with
          | Some rs' => Some (mkC q' L ls rs')
          | None => None
          end
        | None => None
        end
      else None
    end
  | mkC q L ls rs =>
    match ls with
    | [] =>
      if cL then
        match brun_L q (zeros kk) with
        | Some (q', L, w') =>
          if q_eq q' q then None else
          match spush G cR w' cone rs with
          | Some rs' => Some (mkC q' L [] rs')
          | None => None
          end
        | Some (q', R, w') =>
          match spush G cL w' cone [] with
          | Some ls' => Some (mkC q' R ls' rs)
          | None => None
          end
        | None => None
        end
      else None
    | (w, e) :: ys =>
      if implied G (aadd e (aconst (-1))) then
        match brun_L q w with
        | Some (q', L, w') =>
          if q_eq q' q then
            match spush G cR w' e rs with
            | Some rs' => Some (mkC q L ys rs')
            | None => None
            end
          else
            match spush G cR w' cone rs with
            | Some rs' => Some (mkC q' L (dec1 w e ys) rs')
            | None => None
            end
        | Some (q', R, w') =>
          match spush G cL w' cone (dec1 w e ys) with
          | Some ls' => Some (mkC q' R ls' rs)
          | None => None
          end
        | None => None
        end
      else None
    end
  end.

Lemma to_nat_one : Z.to_nat (aeval (fun _ => 0) cone) = 1%nat.
Proof. reflexivity. Qed.
Lemma aeval_cone rho : aeval rho cone = 1.
Proof. apply aeval_aconst. Qed.

Lemma pow1 (w : list Sym) (t : side) : w ^^ 1 *> t = w *> t.
Proof. cbn [lpow]. rewrite app_nil_r. reflexivity. Qed.

Lemma exec_step_spec rho G cL cR tl tr c c' :
  holds rho G -> (cL = true -> tl = const S0) -> (cR = true -> tr = const S0) ->
  exec_step G cL cR c = Some c' ->
  den rho tl tr c -->+ den rho tl tr c'.
Proof.
  intros HG HL HR H.
  destruct c as [q [] ls rs]; cbn [exec_step] in H.
  - (* moving left *)
    destruct ls as [| [w e] ys].
    + destruct cL eqn:EcL; [| discriminate].
      assert (Etl : tl = const S0) by (apply HL; reflexivity).
      destruct (brun_L q (zeros kk)) as [[[q1 []] w1] |] eqn:Eb; [| | discriminate].
      * destruct (q_eq q1 q); [discriminate |].
        destruct (spush G cR w1 cone rs) as [rs' |] eqn:Ep; inversion H; subst c'; clear H.
        unfold den; cbn [cq cd cl cr sden].
        pose proof (brun_L_spec q (zeros kk) q1 L w1 tl (sden rho rs tr) Eb) as Hb.
        cbn [cfg] in Hb. cbn [cfg].
        rewrite Etl in *. rewrite zeros_word in Hb.
        erewrite (spush_spec rho G cR w1 cone rs rs' tr); [| exact HG | exact HR | exact Ep].
        rewrite aeval_cone. rewrite pow1. exact Hb.
      * destruct (spush G true w1 cone []) as [ls' |] eqn:Ep; inversion H; subst c'; clear H.
        unfold den; cbn [cq cd cl cr sden].
        pose proof (brun_L_spec q (zeros kk) q1 R w1 tl (sden rho rs tr) Eb) as Hb.
        cbn [cfg] in Hb. cbn [cfg].
        rewrite Etl in *. rewrite zeros_word in Hb.
        erewrite (spush_spec rho G true w1 cone [] ls' (const S0)); [| exact HG | reflexivity | exact Ep].
        rewrite aeval_cone. rewrite pow1. exact Hb.
    + destruct (implied G (aadd e (aconst (-1)))) eqn:Ei; [| discriminate].
      pose proof (implied_spec rho G _ HG Ei) as He. rewrite aeval_aadd, aeval_aconst in He.
      destruct (brun_L q w) as [[[q1 []] w1] |] eqn:Eb; [| | discriminate].
      * destruct (q_eq q1 q) eqn:Eq.
        -- apply q_eq_spec in Eq. subst q1.
           destruct (spush G cR w1 e rs) as [rs' |] eqn:Ep; inversion H; subst c'; clear H.
           unfold den; cbn [cq cd cl cr sden]. cbn [cfg].
           erewrite (spush_spec rho G cR w1 e rs rs' tr); [| exact HG | exact HR | exact Ep].
           destruct (Z.to_nat (aeval rho e)) as [| n] eqn:En; [lia |].
           exact (chain_L q w w1 n _ _ Eb).
        -- destruct (spush G cR w1 cone rs) as [rs' |] eqn:Ep; inversion H; subst c'; clear H.
           unfold den; cbn [cq cd cl cr].
           pose proof (dec1_spec rho w e ys tl ltac:(lia)) as Hd.
           cbn [sden] in Hd |- *. rewrite Hd. cbn [cfg].
           erewrite (spush_spec rho G cR w1 cone rs rs' tr); [| exact HG | exact HR | exact Ep].
           rewrite aeval_cone, pow1. exact (brun_L_spec q w q1 L w1 _ _ Eb).
      * destruct (spush G cL w1 cone (dec1 w e ys)) as [ls' |] eqn:Ep; inversion H; subst c'; clear H.
        unfold den; cbn [cq cd cl cr].
        pose proof (dec1_spec rho w e ys tl ltac:(lia)) as Hd.
        cbn [sden] in Hd |- *. rewrite Hd. cbn [cfg].
        erewrite (spush_spec rho G cL w1 cone (dec1 w e ys) ls' tl); [| exact HG | exact HL | exact Ep].
        rewrite aeval_cone, pow1. exact (brun_L_spec q w q1 R w1 _ _ Eb).
  - (* moving right *)
    destruct rs as [| [w e] ys].
    + destruct cR eqn:EcR; [| discriminate].
      assert (Etr : tr = const S0) by (apply HR; reflexivity).
      destruct (brun_R q (zeros kk)) as [[[q1 []] w1] |] eqn:Eb; [| | discriminate].
      * destruct (spush G true w1 cone []) as [rs' |] eqn:Ep; inversion H; subst c'; clear H.
        unfold den; cbn [cq cd cl cr sden].
        pose proof (brun_R_spec q (zeros kk) q1 L w1 (sden rho ls tl) tr Eb) as Hb.
        cbn [cfg] in Hb. cbn [cfg].
        rewrite Etr in *. rewrite zeros_word in Hb.
        erewrite (spush_spec rho G true w1 cone [] rs' (const S0)); [| exact HG | reflexivity | exact Ep].
        rewrite aeval_cone. rewrite pow1. exact Hb.
      * destruct (q_eq q1 q); [discriminate |].
        destruct (spush G cL w1 cone ls) as [ls' |] eqn:Ep; inversion H; subst c'; clear H.
        unfold den; cbn [cq cd cl cr sden].
        pose proof (brun_R_spec q (zeros kk) q1 R w1 (sden rho ls tl) tr Eb) as Hb.
        cbn [cfg] in Hb. cbn [cfg].
        rewrite Etr in *. rewrite zeros_word in Hb.
        erewrite (spush_spec rho G cL w1 cone ls ls' tl); [| exact HG | exact HL | exact Ep].
        rewrite aeval_cone. rewrite pow1. exact Hb.
    + destruct (implied G (aadd e (aconst (-1)))) eqn:Ei; [| discriminate].
      pose proof (implied_spec rho G _ HG Ei) as He. rewrite aeval_aadd, aeval_aconst in He.
      destruct (brun_R q w) as [[[q1 []] w1] |] eqn:Eb; [| | discriminate].
      * destruct (spush G cR w1 cone (dec1 w e ys)) as [rs' |] eqn:Ep; inversion H; subst c'; clear H.
        unfold den; cbn [cq cd cl cr].
        pose proof (dec1_spec rho w e ys tr ltac:(lia)) as Hd.
        cbn [sden] in Hd |- *. rewrite Hd. cbn [cfg].
        erewrite (spush_spec rho G cR w1 cone (dec1 w e ys) rs' tr); [| exact HG | exact HR | exact Ep].
        rewrite aeval_cone, pow1. exact (brun_R_spec q w q1 L w1 _ _ Eb).
      * destruct (q_eq q1 q) eqn:Eq.
        -- apply q_eq_spec in Eq. subst q1.
           destruct (spush G cL w1 e ls) as [ls' |] eqn:Ep; inversion H; subst c'; clear H.
           unfold den; cbn [cq cd cl cr sden]. cbn [cfg].
           erewrite (spush_spec rho G cL w1 e ls ls' tl); [| exact HG | exact HL | exact Ep].
           destruct (Z.to_nat (aeval rho e)) as [| n] eqn:En; [lia |].
           exact (chain_R q w w1 n _ _ Eb).
        -- destruct (spush G cL w1 cone ls) as [ls' |] eqn:Ep; inversion H; subst c'; clear H.
           unfold den; cbn [cq cd cl cr].
           pose proof (dec1_spec rho w e ys tr ltac:(lia)) as Hd.
           cbn [sden] in Hd |- *. rewrite Hd. cbn [cfg].
           erewrite (spush_spec rho G cL w1 cone ls ls' tl); [| exact HG | exact HL | exact Ep].
           rewrite aeval_cone, pow1. exact (brun_R_spec q w q1 R w1 _ _ Eb).
Qed.

(* ---------- rules ---------- *)
Record Rule := mkRule {
  r_q : Q; r_d : dir;
  r_L : Stk; r_cL : bool;
  r_R : Stk; r_cR : bool;
  r_G : list Aff;
  r_q' : Q; r_d' : dir;
  r_L' : Stk; r_R' : Stk;
  r_rep : bool; r_dy : list Z
}.

Definition lhs (r : Rule) : Cfg := mkC (r_q r) (r_d r) (r_L r) (r_R r).
Definition rhs (r : Rule) : Cfg := mkC (r_q' r) (r_d' r) (r_L' r) (r_R' r).

Definition Valid (r : Rule) : Prop :=
  forall rho, holds rho (r_G r) ->
  forall tl tr, (r_cL r = true -> tl = const S0) -> (r_cR r = true -> tr = const S0) ->
  den rho tl tr (lhs r) -->+ den rho tl tr (rhs r).

Definition ssub (f : nat -> Aff) (xs : Stk) : Stk :=
  map (fun p => (fst p, asubst f (snd p))) xs.

Lemma ssub_spec rho f xs t : sden rho (ssub f xs) t = sden (vcomp rho f) xs t.
Proof.
  induction xs as [| [w e] u IH]; cbn [ssub map sden fst snd]; [reflexivity |].
  unfold ssub in IH. rewrite IH, asubst_spec. reflexivity.
Qed.

(* strip the instance of a window from the top of a stack *)
Fixpoint strip (f : nat -> Aff) (win : Stk) (xs : Stk) : option Stk :=
  match win, xs with
  | [], _ => Some xs
  | (w, e) :: win', (w2, e2) :: ys =>
    if weq w w2 && aeq (asubst f e) e2 then strip f win' ys else None
  | _, _ => None
  end.

Lemma strip_spec rho f win xs ys t :
  strip f win xs = Some ys ->
  sden rho xs t = sden (vcomp rho f) win (sden rho ys t).
Proof.
  revert xs. induction win as [| [w e] win' IH]; intros xs H; cbn [strip] in H.
  - inversion H; subst. reflexivity.
  - destruct xs as [| [w2 e2] zs]; [discriminate |].
    destruct (weq w w2 && aeq (asubst f e) e2) eqn:E; [| discriminate].
    apply andb_prop in E. destruct E as [E1 E2]. apply weq_spec in E1. subst w2.
    apply (aeq_spec rho) in E2. rewrite asubst_spec in E2.
    cbn [sden]. rewrite <- E2, (IH _ H). reflexivity.
Qed.

Definition rule_app1 (G : list Aff) (cL cR : bool) (r : Rule) (f : nat -> Aff) (c : Cfg) : option Cfg :=
  if q_eq (cq c) (r_q r) && dir_eq (cd c) (r_d r) then
    match strip f (r_L r) (cl c), strip f (r_R r) (cr c) with
    | Some restL, Some restR =>
      if (if r_cL r then cL && match restL with [] => true | _ => false end else true)
         && (if r_cR r then cR && match restR with [] => true | _ => false end else true)
         && forallb (fun g => implied G (asubst f g)) (r_G r)
      then
        match spushes G cL (ssub f (r_L' r)) restL, spushes G cR (ssub f (r_R' r)) restR with
        | Some ls', Some rs' => Some (mkC (r_q' r) (r_d' r) ls' rs')
        | _, _ => None
        end
      else None
    | _, _ => None
    end
  else None.

Lemma holds_subst rho G f gs :
  holds rho G -> forallb (fun g => implied G (asubst f g)) gs = true ->
  holds (vcomp rho f) gs.
Proof.
  intros HG H g Hin. rewrite forallb_forall in H. specialize (H g Hin).
  apply (implied_spec rho) in H; [| exact HG]. rewrite asubst_spec in H. exact H.
Qed.

Lemma rule_app1_spec rho G cL cR tl tr r f c c' :
  Valid r -> holds rho G -> (cL = true -> tl = const S0) -> (cR = true -> tr = const S0) ->
  rule_app1 G cL cR r f c = Some c' ->
  den rho tl tr c -->+ den rho tl tr c'.
Proof.
  intros Hr HG HL HR H. unfold rule_app1 in H.
  destruct (q_eq (cq c) (r_q r) && dir_eq (cd c) (r_d r)) eqn:E0; [| discriminate].
  apply andb_prop in E0. destruct E0 as [E01 E02]. apply q_eq_spec in E01. apply dir_eq_spec in E02.
  destruct (strip f (r_L r) (cl c)) as [restL |] eqn:ES1; [| discriminate].
  destruct (strip f (r_R r) (cr c)) as [restR |] eqn:ES2; [| discriminate].
  match type of H with (if ?x then _ else _) = _ => destruct x eqn:E1 end; [| discriminate].
  apply andb_prop in E1. destruct E1 as [E1 E3]. apply andb_prop in E1. destruct E1 as [E1 E2].
  destruct (spushes G cL (ssub f (r_L' r)) restL) as [ls' |] eqn:EP1; [| discriminate].
  destruct (spushes G cR (ssub f (r_R' r)) restR) as [rs' |] eqn:EP2; [| discriminate].
  inversion H; subst c'; clear H.
  pose proof (holds_subst rho G f (r_G r) HG E3) as Hg.
  unfold den. cbn [cq cd cl cr].
  rewrite (strip_spec rho f _ _ _ tl ES1), (strip_spec rho f _ _ _ tr ES2).
  rewrite E01, E02.
  rewrite (spushes_spec rho G cL _ _ _ tl HG HL EP1), (spushes_spec rho G cR _ _ _ tr HG HR EP2).
  rewrite !ssub_spec.
  apply (Hr (vcomp rho f) Hg (sden rho restL tl) (sden rho restR tr)).
  - intros Hc. rewrite Hc in E1. apply andb_prop in E1. destruct E1 as [E1a E1b].
    destruct restL; [| discriminate]. cbn [sden]. apply HL, E1a.
  - intros Hc. rewrite Hc in E2. apply andb_prop in E2. destruct E2 as [E2a E2b].
    destruct restR; [| discriminate]. cbn [sden]. apply HR, E2a.
Qed.

(* repeated application: rhs = lhs with y := y + dy *)
Definition dyf (dy : list Z) : nat -> Aff := fun i => (nth i dy 0, [(i, 1)]).

Definition vplus (rho : Val) (dy : list Z) (n : Z) : Val := fun i => rho i + n * nth i dy 0.

Lemma vcomp_dyf rho dy i : vcomp rho (dyf dy) i = vplus rho dy 1 i.
Proof. unfold vcomp, dyf, vplus, aeval. cbn [fst snd lsum]. lia. Qed.

Fixpoint stk_eq (a b : Stk) : bool :=
  match a, b with
  | [], [] => true
  | (w, e) :: a', (w2, e2) :: b' => weq w w2 && aeq e e2 && stk_eq a' b'
  | _, _ => false
  end.

Lemma stk_eq_spec rho a b t : stk_eq a b = true -> sden rho a t = sden rho b t.
Proof.
  revert b. induction a as [| [w e] a' IH]; intros b H; destruct b as [| [w2 e2] b']; cbn [stk_eq] in H;
    try discriminate; [reflexivity |].
  apply andb_prop in H. destruct H as [H H3]. apply andb_prop in H. destruct H as [H1 H2].
  apply weq_spec in H1. subst w2. apply (aeq_spec rho) in H2. cbn [sden]. rewrite H2, (IH _ H3). reflexivity.
Qed.

Definition rep_ok (r : Rule) : bool :=
  q_eq (r_q' r) (r_q r) && dir_eq (r_d' r) (r_d r)
  && stk_eq (r_L' r) (ssub (dyf (r_dy r)) (r_L r))
  && stk_eq (r_R' r) (ssub (dyf (r_dy r)) (r_R r)).

Lemma sden_ext rho rho' xs t :
  (forall i, rho i = rho' i) -> sden rho xs t = sden rho' xs t.
Proof.
  intros H. induction xs as [| [w e] u IH]; cbn [sden]; [reflexivity |].
  rewrite IH. f_equal. f_equal. f_equal.
  unfold aeval. f_equal. destruct e as [c l]. cbn [snd]. induction l as [| [v a] t' IHl]; cbn [lsum]; [reflexivity |].
  rewrite IHl, H. reflexivity.
Qed.

Lemma lsum_vplus rho dy n l :
  lsum (vplus rho dy n) l = lsum rho l + n * lsum (fun i => nth i dy 0) l.
Proof.
  induction l as [| [v a] t IH]; cbn [lsum]; [lia |].
  rewrite IH. unfold vplus. nia.
Qed.

Definition gD (dy : list Z) (g : Aff) : Z := lsum (fun i => nth i dy 0) (snd g).

Lemma aeval_vplus rho dy n g : aeval (vplus rho dy n) g = aeval rho g + n * gD dy g.
Proof. unfold aeval, gD. rewrite lsum_vplus. lia. Qed.

Lemma vplus_add rho dy a b i : vplus (vplus rho dy a) dy b i = vplus rho dy (a + b) i.
Proof. unfold vplus. lia. Qed.

Lemma rep_run r rho tl tr n :
  Valid r -> rep_ok r = true ->
  (r_cL r = true -> tl = const S0) -> (r_cR r = true -> tr = const S0) ->
  (forall g, In g (r_G r) -> 0 <= aeval rho g /\ 0 <= aeval rho g + Z.of_nat n * gD (r_dy r) g) ->
  den rho tl tr (lhs r) -->+ den (vplus rho (r_dy r) (Z.of_nat (S n))) tl tr (lhs r).
Proof.
  intros Hr Hok HL HR. revert rho. induction n as [| n IH]; intros rho Hg.
  - (* one application *)
    unfold rep_ok in Hok. apply andb_prop in Hok. destruct Hok as [Hok H4].
    apply andb_prop in Hok. destruct Hok as [Hok H3]. apply andb_prop in Hok. destruct Hok as [H1 H2].
    apply q_eq_spec in H1. apply dir_eq_spec in H2.
    pose proof (Hr rho (fun g Hin => proj1 (Hg g Hin)) tl tr HL HR) as Hs.
    unfold den in Hs |- *. cbn [lhs rhs cq cd cl cr] in Hs |- *.
    rewrite (stk_eq_spec rho _ _ tl H3), (stk_eq_spec rho _ _ tr H4), !ssub_spec, H1, H2 in Hs.
    rewrite (sden_ext (vplus rho (r_dy r) (Z.of_nat 1)) (vcomp rho (dyf (r_dy r))) (r_L r) tl)
      by (intros i; rewrite vcomp_dyf; reflexivity).
    rewrite (sden_ext (vplus rho (r_dy r) (Z.of_nat 1)) (vcomp rho (dyf (r_dy r))) (r_R r) tr)
      by (intros i; rewrite vcomp_dyf; reflexivity).
    exact Hs.
  - (* n+1 applications: one then n *)
    eapply progress_trans.
    + apply (IH rho). intros g Hin. destruct (Hg g Hin) as [H1 H2]. split; [exact H1 |].
      destruct (Z.leb_spec 0 (gD (r_dy r) g)); nia.
    + (* the last application at rho + (n+1) dy *)
      assert (H1 : Valid r) by exact Hr.
      unfold rep_ok in Hok. apply andb_prop in Hok. destruct Hok as [Hok H4].
      apply andb_prop in Hok. destruct Hok as [Hok H3]. apply andb_prop in Hok. destruct Hok as [H5 H2].
      apply q_eq_spec in H5. apply dir_eq_spec in H2.
      set (rho1 := vplus rho (r_dy r) (Z.of_nat (S n))).
      assert (Hg1 : holds rho1 (r_G r)).
      { intros g Hin. unfold rho1. rewrite aeval_vplus. destruct (Hg g Hin) as [Ha Hb].
        rewrite Nat2Z.inj_succ in *. lia. }
      pose proof (Hr rho1 Hg1 tl tr HL HR) as Hs.
      unfold den in Hs |- *. cbn [lhs rhs cq cd cl cr] in Hs |- *.
      rewrite (stk_eq_spec rho1 _ _ tl H3), (stk_eq_spec rho1 _ _ tr H4), !ssub_spec, H5, H2 in Hs.
      rewrite (sden_ext (vplus rho (r_dy r) (Z.of_nat (S (S n)))) (vcomp rho1 (dyf (r_dy r))) (r_L r) tl).
      2:{ intros i. rewrite vcomp_dyf. unfold rho1. rewrite vplus_add.
          assert (Ez : Z.of_nat (S (S n)) = Z.of_nat (S n) + 1) by lia. rewrite Ez. reflexivity. }
      rewrite (sden_ext (vplus rho (r_dy r) (Z.of_nat (S (S n)))) (vcomp rho1 (dyf (r_dy r))) (r_R r) tr).
      2:{ intros i. rewrite vcomp_dyf. unfold rho1. rewrite vplus_add.
          assert (Ez : Z.of_nat (S (S n)) = Z.of_nat (S n) + 1) by lia. rewrite Ez. reflexivity. }
      exact Hs.
Qed.

(* application k times, k an affine expression >= 1 *)
Definition fplus (f : nat -> Aff) (dy : list Z) (k : Aff) : nat -> Aff :=
  fun i => aadd (f i) (ascale (nth i dy 0) k).

Definition rule_appk (G : list Aff) (cL cR : bool) (r : Rule) (f : nat -> Aff) (k : Aff) (c : Cfg) : option Cfg :=
  if r_rep r && rep_ok r && q_eq (cq c) (r_q r) && dir_eq (cd c) (r_d r)
     && implied G (aadd k (aconst (-1))) then
    match strip f (r_L r) (cl c), strip f (r_R r) (cr c) with
    | Some restL, Some restR =>
      if (if r_cL r then cL && match restL with [] => true | _ => false end else true)
         && (if r_cR r then cR && match restR with [] => true | _ => false end else true)
         && forallb (fun g => implied G (asubst f g)
                      && (Z.leb 0 (gD (r_dy r) g)
                          || implied G (aadd (asubst f g) (ascale (gD (r_dy r) g) (aadd k (aconst (-1)))))))
              (r_G r)
      then
        Some (mkC (r_q r) (r_d r) (ssub (fplus f (r_dy r) k) (r_L r) ++ restL)
                 (ssub (fplus f (r_dy r) k) (r_R r) ++ restR))
      else None
    | _, _ => None
    end
  else None.

Lemma sden_app rho xs ys t : sden rho (xs ++ ys) t = sden rho xs (sden rho ys t).
Proof. induction xs as [| [w e] u IH]; cbn [app sden]; [reflexivity | rewrite IH; reflexivity]. Qed.

Lemma rule_appk_spec rho G cL cR tl tr r f k c c' :
  Valid r -> holds rho G -> (cL = true -> tl = const S0) -> (cR = true -> tr = const S0) ->
  rule_appk G cL cR r f k c = Some c' ->
  den rho tl tr c -->+ den rho tl tr c'.
Proof.
  intros Hr HG HL HR H. unfold rule_appk in H.
  match type of H with (if ?x then _ else _) = _ => destruct x eqn:E0 end; [| discriminate].
  apply andb_prop in E0. destruct E0 as [E0 Ek]. apply andb_prop in E0. destruct E0 as [E0 E02].
  apply andb_prop in E0. destruct E0 as [E0 E01]. apply andb_prop in E0. destruct E0 as [_ Eok].
  apply q_eq_spec in E01. apply dir_eq_spec in E02.
  apply (implied_spec rho) in Ek; [| exact HG]. rewrite aeval_aadd, aeval_aconst in Ek.
  destruct (strip f (r_L r) (cl c)) as [restL |] eqn:ES1; [| discriminate].
  destruct (strip f (r_R r) (cr c)) as [restR |] eqn:ES2; [| discriminate].
  match type of H with (if ?x then _ else _) = _ => destruct x eqn:E1 end; [| discriminate].
  apply andb_prop in E1. destruct E1 as [E1 E3]. apply andb_prop in E1. destruct E1 as [E1 E2].
  inversion H; subst c'; clear H.
  set (rho1 := vcomp rho f).
  set (n := Z.to_nat (aeval rho k - 1)).
  assert (En : Z.of_nat n = aeval rho k - 1) by (unfold n; lia).
  assert (Hg : forall g, In g (r_G r) -> 0 <= aeval rho1 g /\ 0 <= aeval rho1 g + Z.of_nat n * gD (r_dy r) g).
  { intros g Hin. rewrite forallb_forall in E3. specialize (E3 g Hin).
    apply andb_prop in E3. destruct E3 as [Ea Eb].
    apply (implied_spec rho) in Ea; [| exact HG]. rewrite asubst_spec in Ea.
    split; [exact Ea |]. rewrite En. unfold rho1.
    destruct (Z.leb_spec 0 (gD (r_dy r) g)) as [HD | HD].
    - nia.
    - cbn [orb] in Eb. apply (implied_spec rho) in Eb; [| exact HG].
      rewrite aeval_aadd, aeval_ascale, aeval_aadd, aeval_aconst, asubst_spec in Eb. nia. }
  assert (HL1 : r_cL r = true -> sden rho restL tl = const S0).
  { intros Hc. rewrite Hc in E1. apply andb_prop in E1. destruct E1 as [E1a E1b].
    destruct restL; [| discriminate]. cbn [sden]. apply HL, E1a. }
  assert (HR1 : r_cR r = true -> sden rho restR tr = const S0).
  { intros Hc. rewrite Hc in E2. apply andb_prop in E2. destruct E2 as [E2a E2b].
    destruct restR; [| discriminate]. cbn [sden]. apply HR, E2a. }
  pose proof (rep_run r rho1 _ _ n Hr Eok HL1 HR1 Hg) as Hrun.
  unfold den in Hrun |- *. cbn [lhs cq cd cl cr] in Hrun |- *.
  rewrite (strip_spec rho f _ _ _ tl ES1), (strip_spec rho f _ _ _ tr ES2), E01, E02.
  rewrite !sden_app, !ssub_spec.
  rewrite (sden_ext (vcomp rho (fplus f (r_dy r) k)) (vplus rho1 (r_dy r) (Z.of_nat (S n))) (r_L r)).
  2:{ intros i. unfold vcomp, fplus, vplus, rho1, vcomp. rewrite aeval_aadd, aeval_ascale, Nat2Z.inj_succ, En.
      replace (Z.succ (aeval rho k - 1)) with (aeval rho k) by lia. ring. }
  rewrite (sden_ext (vcomp rho (fplus f (r_dy r) k)) (vplus rho1 (r_dy r) (Z.of_nat (S n))) (r_R r)).
  2:{ intros i. unfold vcomp, fplus, vplus, rho1, vcomp. rewrite aeval_aadd, aeval_ascale, Nat2Z.inj_succ, En.
      replace (Z.succ (aeval rho k - 1)) with (aeval rho k) by lia. ring. }
  exact Hrun.
Qed.

(* ---------- actions: the sigma and k may be guessed by unverified code ---------- *)
Inductive Act :=
  | AS (n : positive)
  | AR (i : positive)
  | ARK (i : positive) (k : Aff).

(* guess the binding from the stack *)
Fixpoint alook (s : list (nat * Aff)) (i : nat) : Aff :=
  match s with
  | [] => (0, [])
  | (j, e) :: t => if Nat.eqb i j then e else alook t i
  end.

Definition adiv (e : Aff) (m : Z) : Aff :=
  if Z.eqb m 1 then e else (Z.div (fst e) m, map (fun p => (fst p, Z.div (snd p) m)) (snd e)).

Fixpoint guess1 (win xs : Stk) (acc : list (nat * Aff)) : list (nat * Aff) :=
  match win, xs with
  | (_, (c, [(v, m)])) :: win', (_, e) :: ys =>
    guess1 win' ys ((v, adiv (aadd e (aconst (- c))) m) :: acc)
  | _ :: win', _ :: ys => guess1 win' ys acc
  | _, _ => acc
  end.

Definition guess_sigma (r : Rule) (c : Cfg) : nat -> Aff :=
  alook (guess1 (r_R r) (cr c) (guess1 (r_L r) (cl c) [])).

(* numeric k: the smallest bound among decreasing guards (only sensible when everything is constant) *)
Definition guess_k (r : Rule) (f : nat -> Aff) : Aff :=
  aconst (fold_left (fun acc g =>
     let d := gD (r_dy r) g in
     if Z.ltb d 0 then
       let kk1 := Z.div (fst (asubst f g)) (- d) + 1 in
       if Z.ltb acc 0 then kk1 else Z.min acc kk1
     else acc) (r_G r) (-1)).

(* the rule table: a binary tree, so an index costs log space in the checker *)
Inductive RT := TLeaf | TNode (a : RT) (o : option Rule) (b : RT).

Fixpoint rget (t : RT) (p : positive) : option Rule :=
  match t with
  | TLeaf => None
  | TNode a o b =>
    match p with
    | xH => o
    | xO p' => rget a p'
    | xI p' => rget b p'
    end
  end.

Fixpoint rset (t : RT) (p : positive) (x : Rule) : RT :=
  match p with
  | xH =>
    match t with
    | TLeaf => TNode TLeaf (Some x) TLeaf
    | TNode a _ b => TNode a (Some x) b
    end
  | xO p' =>
    match t with
    | TLeaf => TNode (rset TLeaf p' x) None TLeaf
    | TNode a o b => TNode (rset a p' x) o b
    end
  | xI p' =>
    match t with
    | TLeaf => TNode TLeaf None (rset TLeaf p' x)
    | TNode a o b => TNode a o (rset b p' x)
    end
  end.

Lemma rget_rset t p q x r : rget (rset t p x) q = Some r -> r = x \/ rget t q = Some r.
Proof.
  revert t q. induction p as [p IH | p IH |]; intros t q H;
    destruct t as [| a o b]; destruct q as [q | q |]; cbn [rset rget] in H |- *;
    first [ discriminate | exact (IH _ _ H) | (right; exact H) | (left; congruence) ].
Qed.

Variable rules : RT.

Definition AllValid : Prop := forall i r, rget rules i = Some r -> Valid r.

Definition rnth (i : positive) : option Rule := rget rules i.

Fixpoint pos_iter (p : positive) (g : Cfg -> option Cfg) (c : Cfg) : option Cfg :=
  (* p applications of g *)
  match p with
  | xH => g c
  | xO p' =>
    match pos_iter p' g c with
    | Some c1 => pos_iter p' g c1
    | None => None
    end
  | xI p' =>
    match g c with
    | None => None
    | Some c0 =>
      match pos_iter p' g c0 with
      | Some c1 => pos_iter p' g c1
      | None => None
      end
    end
  end.

Lemma pos_iter_spec (P : Cfg -> Cfg -> Prop) (g : Cfg -> option Cfg) :
  (forall c c', g c = Some c' -> P c c') ->
  (forall a b c, P a b -> P b c -> P a c) ->
  forall p c c', pos_iter p g c = Some c' -> P c c'.
Proof.
  intros Hg Ht. induction p as [p IH | p IH |]; intros c c' H; cbn [pos_iter] in H.
  - destruct (g c) as [c0 |] eqn:E0; [| discriminate].
    destruct (pos_iter p g c0) as [c1 |] eqn:E1; [| discriminate].
    eapply Ht; [apply Hg, E0 |]. eapply Ht; [apply IH, E1 | apply IH, H].
  - destruct (pos_iter p g c) as [c1 |] eqn:E1; [| discriminate].
    eapply Ht; [apply IH, E1 | apply IH, H].
  - apply Hg, H.
Qed.

Definition exec_act (G : list Aff) (cL cR : bool) (a : Act) (c : Cfg) : option Cfg :=
  match a with
  | AS p => pos_iter p (exec_step G cL cR) c
  | AR i =>
    match rnth i with
    | None => None
    | Some r =>
      let f := guess_sigma r c in
      if r_rep r then rule_appk G cL cR r f (guess_k r f) c
      else rule_app1 G cL cR r f c
    end
  | ARK i k =>
    match rnth i with
    | None => None
    | Some r => rule_appk G cL cR r (guess_sigma r c) k c
    end
  end.

Lemma exec_act_spec rho G cL cR tl tr a c c' :
  AllValid -> holds rho G -> (cL = true -> tl = const S0) -> (cR = true -> tr = const S0) ->
  exec_act G cL cR a c = Some c' ->
  den rho tl tr c -->+ den rho tl tr c'.
Proof.
  intros HV HG HL HR H. destruct a as [p | i | i k]; cbn [exec_act] in H.
  - apply (pos_iter_spec (fun c1 c2 => den rho tl tr c1 -->+ den rho tl tr c2) (exec_step G cL cR)) with (p := p).
    + intros c1 c2 Hc. eapply exec_step_spec; eauto.
    + intros x y z Hx Hy. eapply progress_trans; eauto.
    + exact H.
  - unfold rnth in H. destruct (rget rules i) as [r |] eqn:Er; [| discriminate].
    pose proof (HV i r Er) as Hr.
    destruct (r_rep r).
    + eapply rule_appk_spec; eauto.
    + eapply rule_app1_spec; eauto.
  - unfold rnth in H. destruct (rget rules i) as [r |] eqn:Er; [| discriminate].
    pose proof (HV i r Er) as Hr.
    eapply rule_appk_spec; eauto.
Qed.

Fixpoint exec_acts (G : list Aff) (cL cR : bool) (acts : list Act) (c : Cfg) : option Cfg :=
  match acts with
  | [] => Some c
  | a :: t =>
    match exec_act G cL cR a c with
    | None => None
    | Some c1 => exec_acts G cL cR t c1
    end
  end.

Lemma exec_acts_star rho G cL cR tl tr acts c c' :
  AllValid -> holds rho G -> (cL = true -> tl = const S0) -> (cR = true -> tr = const S0) ->
  exec_acts G cL cR acts c = Some c' ->
  den rho tl tr c -->* den rho tl tr c'.
Proof.
  intros HV HG HL HR. revert c. induction acts as [| a t IH]; intros c H; cbn [exec_acts] in H.
  - inversion H; subst. apply evstep_refl.
  - destruct (exec_act G cL cR a c) as [c1 |] eqn:E; [| discriminate].
    eapply evstep_trans; [apply progress_evstep; eapply exec_act_spec; eauto | apply IH, H].
Qed.

Lemma exec_acts_plus rho G cL cR tl tr a acts c c' :
  AllValid -> holds rho G -> (cL = true -> tl = const S0) -> (cR = true -> tr = const S0) ->
  exec_acts G cL cR (a :: acts) c = Some c' ->
  den rho tl tr c -->+ den rho tl tr c'.
Proof.
  intros HV HG HL HR H. cbn [exec_acts] in H.
  destruct (exec_act G cL cR a c) as [c1 |] eqn:E; [| discriminate].
  eapply progress_evstep_trans; [eapply exec_act_spec; eauto | eapply exec_acts_star; eauto].
Qed.

Definition cfg_eq (a b : Cfg) : bool :=
  q_eq (cq a) (cq b) && dir_eq (cd a) (cd b) && stk_eq (cl a) (cl b) && stk_eq (cr a) (cr b).

Lemma cfg_eq_spec rho tl tr a b : cfg_eq a b = true -> den rho tl tr a = den rho tl tr b.
Proof.
  unfold cfg_eq. intros H. apply andb_prop in H. destruct H as [H H4]. apply andb_prop in H. destruct H as [H H3].
  apply andb_prop in H. destruct H as [H1 H2]. apply q_eq_spec in H1. apply dir_eq_spec in H2.
  unfold den. rewrite H1, H2, (stk_eq_spec rho _ _ tl H3), (stk_eq_spec rho _ _ tr H4). reflexivity.
Qed.

Definition check_rule (r : Rule) (acts : list Act) : bool :=
  match acts with
  | [] => false
  | _ =>
    match exec_acts (r_G r) (r_cL r) (r_cR r) acts (lhs r) with
    | Some c' => cfg_eq c' (rhs r)
    | None => false
    end
  end.

Lemma check_rule_spec r acts : AllValid -> check_rule r acts = true -> Valid r.
Proof.
  intros HV H rho HG tl tr HL HR. unfold check_rule in H.
  destruct acts as [| a t]; [discriminate |].
  destruct (exec_acts (r_G r) (r_cL r) (r_cR r) (a :: t) (lhs r)) as [c' |] eqn:E; [| discriminate].
  rewrite <- (cfg_eq_spec rho tl tr c' (rhs r) H).
  eapply exec_acts_plus; eauto.
Qed.

End Run.

Definition start : Cfg := mkC A R [] [].

Lemma start_den rho : den rho (const S0) (const S0) start = c0.
Proof. reflexivity. Qed.

Definition rho0 : Val := fun _ => 0.

Section Top.
Variable tm : TM.
Variable kk fuel : nat.
Variable allr : RT.
Hypothesis allr_valid : AllValid tm allr.

(* ---------- non-halting: a rule whose right side is its left side under a monotone map ---------- *)
Definition nonneg_coefs (nv : nat) (l : list (nat * Z)) : bool :=
  forallb (fun p => Nat.ltb (fst p) nv && Z.leb 0 (snd p)) l.

Lemma lsum_mono rho rho' nv l :
  (forall i, (i < nv)%nat -> rho i <= rho' i) -> nonneg_coefs nv l = true ->
  lsum rho l <= lsum rho' l.
Proof.
  intros H. induction l as [| [v a] t IH]; cbn [lsum nonneg_coefs forallb]; [lia |].
  unfold nonneg_coefs. cbn [forallb fst snd]. intros Hb.
  apply andb_prop in Hb. destruct Hb as [Hb Ht]. apply andb_prop in Hb. destruct Hb as [H1 H2].
  apply Nat.ltb_lt in H1. apply Z.leb_le in H2.
  pose proof (H v H1). specialize (IH Ht). nia.
Qed.

(* ---------- halting: the ground run ends on a block that runs into an undefined transition ---------- *)
Fixpoint zhalt (n : nat) (q : Q) (d : dir) (ls rs : list Sym) : bool :=
  match n with
  | O => false
  | S n' =>
    match d with
    | L =>
      match ls with
      | [] => false
      | b :: ls' =>
        match tm (q, b) with
        | None => true
        | Some (s, L, q') => zhalt n' q' L ls' (s :: rs)
        | Some (s, R, q') => zhalt n' q' R (s :: ls') rs
        end
      end
    | R =>
      match rs with
      | [] => false
      | b :: rs' =>
        match tm (q, b) with
        | None => true
        | Some (s, L, q') => zhalt n' q' L ls (s :: rs')
        | Some (s, R, q') => zhalt n' q' R (s :: ls) rs'
        end
      end
    end
  end.

Lemma zhalt_spec n q d ls rs l r :
  zhalt n q d ls rs = true -> exists c', cfg q d (ls *> l) (rs *> r) -[ tm ]->* c' /\ halted tm c'.
Proof.
  revert q d ls rs. induction n as [| n IH]; intros q d ls rs H; cbn [zhalt] in H; [discriminate |].
  destruct d.
  - destruct ls as [| b ls0]; [discriminate |].
    destruct (tm (q, b)) as [[[s []] q1] |] eqn:E.
    + destruct (IH _ _ _ _ H) as [c' [H1 H2]]. exists c'. split; [| exact H2].
      eapply evstep_step; [apply (step_at_L tm q b s L q1 (ls0 *> l) (rs *> r) E) | exact H1].
    + destruct (IH _ _ _ _ H) as [c' [H1 H2]]. exists c'. split; [| exact H2].
      eapply evstep_step; [apply (step_at_L tm q b s R q1 (ls0 *> l) (rs *> r) E) | exact H1].
    + eexists. split; [apply evstep_refl |]. cbn. exact E.
  - destruct rs as [| b rs0]; [discriminate |].
    destruct (tm (q, b)) as [[[s []] q1] |] eqn:E.
    + destruct (IH _ _ _ _ H) as [c' [H1 H2]]. exists c'. split; [| exact H2].
      eapply evstep_step; [apply (step_at_R tm q b s L q1 (ls *> l) (rs0 *> r) E) | exact H1].
    + destruct (IH _ _ _ _ H) as [c' [H1 H2]]. exists c'. split; [| exact H2].
      eapply evstep_step; [apply (step_at_R tm q b s R q1 (ls *> l) (rs0 *> r) E) | exact H1].
    + eexists. split; [apply evstep_refl |]. cbn. exact E.
Qed.

Lemma halts_from_evstep c c' : c -[ tm ]->* c' -> halted tm c' -> halts tm c.
Proof.
  intros H1 H2. destruct (with_counter H1) as [n Hn].
  exists n. exists c'. split; [exact Hn | exact H2].
Qed.

(* ---------- stages: reachable instances of symbolic configurations ---------- *)
Lemma holds_app_local rho G1 G2 : holds rho G1 -> holds rho G2 -> holds rho (G1 ++ G2).
Proof. intros H1 H2 g Hin. apply in_app_or in Hin. destruct Hin as [Hin | Hin]; [apply H1 | apply H2]; exact Hin. Qed.

Definition Reach (S : Cfg) (G : list Aff) : Prop :=
  exists rho, holds rho G /\ c0 -[ tm ]->* den rho (const S0) (const S0) S.

Lemma reach_start : Reach start [].
Proof.
  exists rho0. split; [intros g [] |].
  rewrite (start_den rho0). apply evstep_refl.
Qed.

Lemma reach_exec S G acts S' : Reach S G ->
  exec_acts tm kk fuel allr G true true acts S = Some S' -> Reach S' G.
Proof.
  intros [rho [HG Hr]] H. exists rho. split; [exact HG |].
  eapply evstep_trans; [exact Hr |].
  exact (exec_acts_star tm kk fuel allr rho G true true (const S0) (const S0) acts S S' allr_valid HG
           (fun _ => eq_refl) (fun _ => eq_refl) H).
Qed.

(* the map of a closed diagonal rule *)
Definition mapf (F : list (Z * Z)) : nat -> Aff :=
  fun i => let p := nth i F (1, 0) in (snd p, [(i, fst p)]).

Definition stepv (F : list (Z * Z)) (rho : Val) : Val := vcomp rho (mapf F).

Lemma stepv_eq F rho i :
  stepv F rho i = fst (nth i F (1, 0)) * rho i + snd (nth i F (1, 0)).
Proof. unfold stepv, vcomp, mapf, aeval. cbn [fst snd lsum]. lia. Qed.

Fixpoint iterv (F : list (Z * Z)) (n : nat) (rho : Val) : Val :=
  match n with
  | O => rho
  | S n' => iterv F n' (stepv F rho)
  end.

Definition goodF (F : list (Z * Z)) : bool :=
  forallb (fun p => Z.eqb (fst p) 1 || (Z.leb 2 (fst p) && Z.leb 0 (snd p))) F.

Lemma goodF_nth F i : goodF F = true ->
  fst (nth i F (1, 0)) = 1 \/ (2 <= fst (nth i F (1, 0)) /\ 0 <= snd (nth i F (1, 0))).
Proof.
  intros H. unfold goodF in H. rewrite forallb_forall in H.
  destruct (nth_in_or_default i F (1, 0)) as [Hin | Hd].
  - specialize (H _ Hin). apply orb_prop in H. destruct H as [H | H].
    + left. apply Z.eqb_eq in H. exact H.
    + right. apply andb_prop in H. destruct H as [H1 H2]. apply Z.leb_le in H1. apply Z.leb_le in H2. lia.
  - rewrite Hd. left. reflexivity.
Qed.

Lemma iterv_spec F n rho i : goodF F = true ->
  (2 <= fst (nth i F (1, 0)) -> 0 <= rho i) ->
  (fst (nth i F (1, 0)) = 1 -> iterv F n rho i = rho i + Z.of_nat n * snd (nth i F (1, 0))) /\
  (2 <= fst (nth i F (1, 0)) -> rho i <= iterv F n rho i).
Proof.
  intros Hg. revert rho. induction n as [| n IH]; intros rho H0.
  - cbn [iterv]. split; intros; lia.
  - cbn [iterv]. pose proof (goodF_nth F i Hg) as Hc.
    assert (H1 : 2 <= fst (nth i F (1, 0)) -> 0 <= stepv F rho i).
    { intros H2. rewrite stepv_eq. specialize (H0 H2). destruct Hc as [Hc | [Hc1 Hc2]]; nia. }
    destruct (IH (stepv F rho) H1) as [IH1 IH2]. split.
    + intros H2. rewrite IH1 by exact H2. rewrite stepv_eq, H2. lia.
    + intros H2. specialize (IH2 H2). rewrite stepv_eq in IH2. specialize (H0 H2).
      destruct Hc as [Hc | [Hc1 Hc2]]; nia.
Qed.

Fixpoint dsum (F : list (Z * Z)) (l : list (nat * Z)) : Z :=
  match l with
  | [] => 0
  | (v, c) :: t => (if Z.eqb (fst (nth v F (1, 0))) 1 then c * snd (nth v F (1, 0)) else 0) + dsum F t
  end.

Definition gmono (F : list (Z * Z)) (l : list (nat * Z)) : bool :=
  forallb (fun p => Z.eqb (fst (nth (fst p) F (1, 0))) 1 || Z.leb 0 (snd p)) l.

Lemma guard_lower F n rho l : goodF F = true -> gmono F l = true ->
  (forall i, 2 <= fst (nth i F (1, 0)) -> 0 <= rho i) ->
  lsum rho l + Z.of_nat n * dsum F l <= lsum (iterv F n rho) l.
Proof.
  intros Hg. induction l as [| [v c] t IH]; intros Hm H0; cbn [lsum dsum]; [lia |].
  unfold gmono in Hm. cbn [forallb fst snd] in Hm. apply andb_prop in Hm. destruct Hm as [Hm1 Hm2].
  specialize (IH Hm2 H0).
  destruct (iterv_spec F n rho v Hg (H0 v)) as [I1 I2].
  destruct (Z.eqb_spec (fst (nth v F (1, 0))) 1) as [E | E].
  - rewrite (I1 E). nia.
  - cbn [orb] in Hm1. apply Z.leb_le in Hm1.
    pose proof (goodF_nth F v Hg) as Hc. destruct Hc as [Hc | [Hc1 Hc2]]; [lia |].
    specialize (I2 Hc1). nia.
Qed.

Fixpoint vars_lt (nv : nat) (l : list (nat * Z)) : bool :=
  match l with
  | [] => true
  | (v, _) :: t => Nat.ltb v nv && vars_lt nv t
  end.

Lemma lsum_vars_lt rho rho' nv l : vars_lt nv l = true -> (forall i, (i < nv)%nat -> rho i = rho' i) ->
  lsum rho l = lsum rho' l.
Proof.
  intros Hv H. induction l as [| [v c] t IH]; cbn [lsum]; [reflexivity |].
  cbn [vars_lt] in Hv. apply andb_prop in Hv. destruct Hv as [H1 H2]. apply Nat.ltb_lt in H1.
  rewrite H by exact H1. rewrite IH by exact H2. reflexivity.
Qed.

Lemma iter_run r F : Valid tm r -> q_eq (r_q' r) (r_q r) = true -> dir_eq (r_d' r) (r_d r) = true ->
  stk_eq (r_L' r) (ssub (mapf F) (r_L r)) = true -> stk_eq (r_R' r) (ssub (mapf F) (r_R r)) = true ->
  forall n rho, (forall j, (j < n)%nat -> holds (iterv F j rho) (r_G r)) ->
  den rho (const S0) (const S0) (lhs r) -[ tm ]->* den (iterv F n rho) (const S0) (const S0) (lhs r).
Proof.
  intros Hr Eq Ed EL ER. apply q_eq_spec in Eq. apply dir_eq_spec in Ed.
  induction n as [| n IH]; intros rho H; cbn [iterv]; [apply evstep_refl |].
  eapply evstep_trans; [| apply IH; intros j Hj; exact (H (S j) ltac:(lia))].
  apply progress_evstep.
  pose proof (Hr rho (H 0%nat ltac:(lia)) (const S0) (const S0) (fun _ => eq_refl) (fun _ => eq_refl)) as Hs.
  unfold den in Hs |- *. cbn [lhs rhs cq cd cl cr] in Hs |- *.
  rewrite (stk_eq_spec rho _ _ _ EL), (stk_eq_spec rho _ _ _ ER), !ssub_spec, Eq, Ed in Hs.
  exact Hs.
Qed.

(* the stage: apply rule r k times at the whole tape; huge fields become fresh variables with a lower bound *)
Definition sigma2 (F : list (Z * Z)) (f : nat -> Aff) (k : Aff) (nvO : nat) : nat -> Aff :=
  fun i => if Z.eqb (fst (nth i F (1, 0))) 1 then aadd (f i) (ascale (snd (nth i F (1, 0))) k)
           else (0, [((nvO + i)%nat, 1)]).

Definition exp_ok (G : list Aff) (r : Rule) (sl : list Aff) (k : Aff) (F : list (Z * Z)) (nvO : nat) (B : list (nat * Z)) (S : Cfg) : bool :=
  let f := fun i => nth i sl (0, []) in
  q_eq (cq S) (r_q r) && dir_eq (cd S) (r_d r) && q_eq (r_q' r) (r_q r) && dir_eq (r_d' r) (r_d r)
  && goodF F && implied G (aadd k (aconst (-1)))
  && stk_eq (r_L' r) (ssub (mapf F) (r_L r)) && stk_eq (r_R' r) (ssub (mapf F) (r_R r))
  && forallb (fun g => vars_lt nvO (snd g)) G
  && forallb (fun e => vars_lt nvO (snd e)) sl && vars_lt nvO (snd k)
  && forallb (fun g => gmono F (snd g) && implied G (asubst f g)
               && (Z.leb 0 (dsum F (snd g))
                   || implied G (aadd (asubst f g) (ascale (dsum F (snd g)) (aadd k (aconst (-1)))))))
       (r_G r)
  && forallb (fun p => Z.leb 2 (fst (nth (fst p) F (1, 0))) && implied G (aadd (f (fst p)) (aconst (- snd p)))) B
  && forallb (fun i => Z.eqb (fst (nth i F (1, 0))) 1 || implied G (f i)) (seq 0 (length F)).

Definition exp_stage (G : list Aff) (r : Rule) (sl : list Aff) (k : Aff) (F : list (Z * Z)) (nvO : nat) (B : list (nat * Z)) (S : Cfg) :
    option (Cfg * list Aff) :=
  let f := fun i => nth i sl (0, []) in
  if exp_ok G r sl k F nvO B S then
    match strip f (r_L r) (cl S), strip f (r_R r) (cr S) with
    | Some [], Some [] =>
      let s2 := sigma2 F f k nvO in
      Some (mkC (r_q r) (r_d r) (ssub s2 (r_L r)) (ssub s2 (r_R r)),
            G ++ map (fun p => (- snd p, [((nvO + fst p)%nat, 1)])) B)
    | _, _ => None
    end
  else None.

Lemma reach_exp S G r sl k F nvO B S' G' : Reach S G -> Valid tm r ->
  exp_stage G r sl k F nvO B S = Some (S', G') -> Reach S' G'.
Proof.
  intros [rho [HG Hr]] Hv H. unfold exp_stage in H.
  destruct (exp_ok G r sl k F nvO B S) eqn:E0; [| discriminate].
  set (f := fun i => nth i sl (0%Z, [])) in *.
  destruct (strip f (r_L r) (cl S)) as [[| ? ?] |] eqn:ES1; try discriminate.
  destruct (strip f (r_R r) (cr S)) as [[| ? ?] |] eqn:ES2; try discriminate.
  inversion H; subst S' G'; clear H.
  unfold exp_ok in E0. fold f in E0.
  apply andb_prop in E0. destruct E0 as [E0 EH].
  apply andb_prop in E0. destruct E0 as [E0 EB].
  apply andb_prop in E0. destruct E0 as [E0 EgR].
  apply andb_prop in E0. destruct E0 as [E0 Evk].
  apply andb_prop in E0. destruct E0 as [E0 Evs].
  apply andb_prop in E0. destruct E0 as [E0 EvG].
  apply andb_prop in E0. destruct E0 as [E0 ER].
  apply andb_prop in E0. destruct E0 as [E0 EL].
  apply andb_prop in E0. destruct E0 as [E0 Ek].
  apply andb_prop in E0. destruct E0 as [E0 Eg].
  apply andb_prop in E0. destruct E0 as [E0 Ed2].
  apply andb_prop in E0. destruct E0 as [E0 Eq2].
  apply andb_prop in E0. destruct E0 as [Eq Ed].
  apply q_eq_spec in Eq. apply dir_eq_spec in Ed.
  set (rho1 := vcomp rho f).
  apply (implied_spec rho) in Ek; [| exact HG]. rewrite aeval_aadd, aeval_aconst in Ek.
  set (n := Z.to_nat (aeval rho k)).
  assert (En : Z.of_nat n = aeval rho k) by (unfold n; lia).
  assert (Hnn : forall i, 2 <= fst (nth i F (1, 0)) -> 0 <= rho1 i).
  { intros i Hi. destruct (lt_dec i (length F)) as [Hlt | Hge].
    - rewrite forallb_forall in EH. assert (Hs : In i (seq 0 (length F))) by (apply in_seq; lia).
      specialize (EH i Hs). apply orb_prop in EH. destruct EH as [EH | EH].
      + apply Z.eqb_eq in EH. lia.
      + apply (implied_spec rho) in EH; [exact EH | exact HG].
    - rewrite nth_overflow in Hi by lia. cbn in Hi. lia. }
  assert (Hgj : forall j, (j < n)%nat -> holds (iterv F j rho1) (r_G r)).
  { intros j Hj g Hing. rewrite forallb_forall in EgR. specialize (EgR g Hing).
    apply andb_prop in EgR. destruct EgR as [EgR E3]. apply andb_prop in EgR. destruct EgR as [E1 E2].
    apply (implied_spec rho) in E2; [| exact HG]. rewrite asubst_spec in E2. fold rho1 in E2.
    pose proof (guard_lower F j rho1 (snd g) Eg E1 Hnn) as Hl.
    unfold aeval in E2 |- *.
    destruct (Z.leb_spec 0 (dsum F (snd g))) as [HD | HD].
    - nia.
    - cbn [orb] in E3. apply (implied_spec rho) in E3; [| exact HG].
      rewrite aeval_aadd, aeval_ascale, aeval_aadd, aeval_aconst, asubst_spec in E3. fold rho1 in E3.
      unfold aeval at 1 in E3. nia. }
  pose proof (iter_run r F Hv Eq2 Ed2 EL ER n rho1 Hgj) as Hrun.
  set (rho2 := fun v : nat => if Nat.ltb v nvO then rho v else iterv F n rho1 (v - nvO)%nat).
  assert (Hlow : forall i, (i < nvO)%nat -> rho i = rho2 i).
  { intros i Hi. unfold rho2. destruct (Nat.ltb_spec i nvO); [reflexivity | lia]. }
  assert (Hval : forall i, vcomp rho2 (sigma2 F f k nvO) i = iterv F n rho1 i).
  { intros i. unfold vcomp at 1, sigma2.
    destruct (iterv_spec F n rho1 i Eg (Hnn i)) as [I1 I2].
    destruct (Z.eqb_spec (fst (nth i F (1, 0))) 1) as [E1 | E1].
    - rewrite aeval_aadd, aeval_ascale.
      assert (Ef : aeval rho2 (f i) = rho1 i).
      { unfold rho1, vcomp, aeval. f_equal. symmetry. eapply lsum_vars_lt; [| exact Hlow].
        unfold f. destruct (nth_in_or_default i sl (0%Z, [])) as [Hi | Hd].
        - rewrite forallb_forall in Evs. apply Evs, Hi.
        - rewrite Hd. reflexivity. }
      assert (Ek2 : aeval rho2 k = aeval rho k).
      { unfold aeval. f_equal. symmetry. eapply lsum_vars_lt; [exact Evk | exact Hlow]. }
      rewrite Ef, Ek2, (I1 E1), En. ring.
    - unfold aeval. cbn [fst snd lsum]. unfold rho2.
      destruct (Nat.ltb_spec (nvO + i) nvO); [lia |].
      replace (nvO + i - nvO)%nat with i by lia. ring. }
  exists rho2. split.
  - apply holds_app_local.
    + intros g Hing. specialize (HG g Hing). unfold aeval in HG |- *.
      rewrite forallb_forall in EvG. rewrite <- (lsum_vars_lt rho rho2 nvO (snd g) (EvG g Hing) Hlow). exact HG.
    + intros g Hing. apply in_map_iff in Hing. destruct Hing as [p [Hp Hinp]]. subst g.
      rewrite forallb_forall in EB. specialize (EB p Hinp). apply andb_prop in EB. destruct EB as [E1 E2].
      apply Z.leb_le in E1. apply (implied_spec rho) in E2; [| exact HG].
      rewrite aeval_aadd, aeval_aconst in E2.
      destruct (iterv_spec F n rho1 (fst p) Eg (Hnn (fst p))) as [_ I2]. specialize (I2 E1).
      unfold aeval. cbn [fst snd lsum]. unfold rho2.
      destruct (Nat.ltb_spec (nvO + fst p) nvO); [lia |].
      replace (nvO + fst p - nvO)%nat with (fst p) by lia.
      assert (Hf1 : aeval rho (f (fst p)) = rho1 (fst p)) by reflexivity.
      assert (Hf2 : aeval rho (nth (fst p) sl (0%Z, [])) = rho1 (fst p)) by reflexivity.
      cbn [fst snd] in *. lia.
  - eapply evstep_trans; [exact Hr |].
    assert (E1 : den rho (const S0) (const S0) S = den rho1 (const S0) (const S0) (lhs r)).
    { unfold den. cbn [lhs cq cd cl cr].
      rewrite (strip_spec rho f _ _ _ (const S0) ES1), (strip_spec rho f _ _ _ (const S0) ES2), Eq, Ed.
      reflexivity. }
    assert (E2 : den rho2 (const S0) (const S0) (mkC (r_q r) (r_d r) (ssub (sigma2 F f k nvO) (r_L r)) (ssub (sigma2 F f k nvO) (r_R r)))
               = den (iterv F n rho1) (const S0) (const S0) (lhs r)).
    { unfold den. cbn [lhs cq cd cl cr]. rewrite !ssub_spec.
      rewrite (sden_ext (vcomp rho2 (sigma2 F f k nvO)) (iterv F n rho1) (r_L r)) by exact Hval.
      rewrite (sden_ext (vcomp rho2 (sigma2 F f k nvO)) (iterv F n rho1) (r_R r)) by exact Hval.
      reflexivity. }
    rewrite E1, E2. exact Hrun.
Qed.

Inductive Stage :=
  | SA (acts : list Act)
  | SX (i : positive) (sl : list Aff) (k : Aff) (F : list (Z * Z)) (nvO : nat) (B : list (nat * Z)).

Fixpoint run_stages (ss : list Stage) (S : Cfg) (G : list Aff) : option (Cfg * list Aff) :=
  match ss with
  | [] => Some (S, G)
  | SA acts :: t =>
    match exec_acts tm kk fuel allr G true true acts S with
    | Some Sx => run_stages t Sx G
    | None => None
    end
  | SX i sl k Fm nvO Bd :: t =>
    match rget allr i with
    | Some r =>
      match exp_stage G r sl k Fm nvO Bd S with
      | Some (Sx, Gx) => run_stages t Sx Gx
      | None => None
      end
    | None => None
    end
  end.

Lemma run_stages_spec ss S G S' G' : Reach S G -> run_stages ss S G = Some (S', G') -> Reach S' G'.
Proof.
  revert S G. induction ss as [| [acts | i sl k Fm nvO Bd] t IH]; intros S G HR H; cbn [run_stages] in H.
  - inversion H; subst. exact HR.
  - destruct (exec_acts tm kk fuel allr G true true acts S) as [Sx |] eqn:E; [| discriminate].
    exact (IH _ _ (reach_exec _ _ _ _ HR E) H).
  - destruct (rget allr i) as [r |] eqn:Er; [| discriminate].
    destruct (exp_stage G r sl k Fm nvO Bd S) as [[Sx Gx] |] eqn:E; [| discriminate].
    exact (IH _ _ (reach_exp _ _ _ _ _ _ _ _ _ _ HR (allr_valid _ _ Er) E) H).
Qed.

(* a monotone cycle from a reachable instance *)
Definition cycle_ok2 (G : list Aff) (r : Rule) (nv : nat) (f sg : nat -> Aff) (S : Cfg) : bool :=
  q_eq (r_q' r) (r_q r) && dir_eq (r_d' r) (r_d r)
  && stk_eq (r_L' r) (ssub f (r_L r)) && stk_eq (r_R' r) (ssub f (r_R r))
  && forallb (fun i => nonneg_coefs nv (snd (f i))) (seq 0 nv)
  && forallb (fun g => nonneg_coefs nv (snd g)) (r_G r)
  && q_eq (cq S) (r_q r) && dir_eq (cd S) (r_d r)
  && match strip sg (r_L r) (cl S), strip sg (r_R r) (cr S) with
     | Some [], Some [] => true
     | _, _ => false
     end
  && forallb (fun g => implied G (asubst sg g)) (r_G r)
  && forallb (fun i => implied G (aadd (asubst sg (f i)) (ascale (-1) (sg i)))) (seq 0 nv).

Theorem cycle_stage S G r nv f sg : Reach S G -> Valid tm r -> cycle_ok2 G r nv f sg S = true -> ~ halts tm c0.
Proof.
  intros [rho [HG Hrun]] Hr Hok. unfold cycle_ok2 in Hok.
  apply andb_prop in Hok. destruct Hok as [Hok E13].
  apply andb_prop in Hok. destruct Hok as [Hok E12].
  apply andb_prop in Hok. destruct Hok as [Hok E9].
  apply andb_prop in Hok. destruct Hok as [Hok E8].
  apply andb_prop in Hok. destruct Hok as [Hok E7].
  apply andb_prop in Hok. destruct Hok as [Hok E6].
  apply andb_prop in Hok. destruct Hok as [Hok E5].
  apply andb_prop in Hok. destruct Hok as [Hok E4].
  apply andb_prop in Hok. destruct Hok as [Hok E3].
  apply andb_prop in Hok. destruct Hok as [E1 E2].
  apply q_eq_spec in E1. apply dir_eq_spec in E2.
  apply q_eq_spec in E7. apply dir_eq_spec in E8.
  destruct (strip sg (r_L r) (cl S)) as [[| ? ?] |] eqn:ES1; try discriminate.
  destruct (strip sg (r_R r) (cr S)) as [[| ? ?] |] eqn:ES2; try discriminate.
  set (C := fun rho : Val => den rho (const S0) (const S0) (lhs r)).
  set (rho1 := vcomp rho sg).
  set (P := fun rho : Val => holds rho (r_G r) /\ forall i, (i < nv)%nat -> rho i <= aeval rho (f i)).
  assert (Hmono : forall rho rho' l, (forall i, (i < nv)%nat -> rho i <= rho' i) -> nonneg_coefs nv l = true ->
                  lsum rho l <= lsum rho' l) by (intros; eapply lsum_mono; eauto).
  assert (HCs : forall rho, P rho -> exists rho', C rho -[ tm ]->+ C rho' /\ P rho').
  { intros rho' [Hg Hi]. exists (vcomp rho' f). split.
    - pose proof (Hr rho' Hg (const S0) (const S0) (fun _ => eq_refl) (fun _ => eq_refl)) as Hs.
      unfold C, den in Hs |- *. cbn [lhs rhs cq cd cl cr] in Hs |- *.
      rewrite (stk_eq_spec rho' _ _ _ E3), (stk_eq_spec rho' _ _ _ E4), !ssub_spec, E1, E2 in Hs.
      exact Hs.
    - split.
      + intros g Hing. rewrite forallb_forall in E6. specialize (E6 g Hing).
        specialize (Hg g Hing). unfold aeval in Hg |- *.
        pose proof (Hmono rho' (vcomp rho' f) (snd g) Hi E6). lia.
      + intros i Hlt. rewrite forallb_forall in E5.
        assert (Hin2 : In i (seq 0 nv)) by (apply in_seq; lia).
        specialize (E5 i Hin2).
        unfold vcomp at 1. unfold aeval at 2. unfold aeval at 1.
        pose proof (Hmono rho' (vcomp rho' f) (snd (f i)) Hi E5). lia. }
  assert (HP0 : P rho1).
  { split.
    - intros g Hing. rewrite forallb_forall in E12. specialize (E12 g Hing).
      apply (implied_spec rho) in E12; [| exact HG]. rewrite asubst_spec in E12. exact E12.
    - intros i Hlt. rewrite forallb_forall in E13.
      assert (Hin2 : In i (seq 0 nv)) by (apply in_seq; lia).
      specialize (E13 i Hin2).
      apply (implied_spec rho) in E13; [| exact HG].
      rewrite aeval_aadd, aeval_ascale, asubst_spec in E13.
      assert (Hx : rho1 i = aeval rho (sg i)) by reflexivity. rewrite Hx. unfold rho1. lia. }
  eapply multistep_nonhalt.
  - exact Hrun.
  - assert (Heq : den rho (const S0) (const S0) S = C rho1).
    { unfold C, den. cbn [lhs cq cd cl cr].
      rewrite (strip_spec rho sg _ _ _ (const S0) ES1), (strip_spec rho sg _ _ _ (const S0) ES2), E7, E8.
      reflexivity. }
    rewrite Heq.
    apply (progress_nonhalt_cond tm _ rho1 C P); [exact HCs | exact HP0].
Qed.

(* halting from a reachable instance *)
Definition halt_final2 (G : list Aff) (c : Cfg) : bool :=
  match cd c with
  | L =>
    match cl c with
    | [] => zhalt fuel (cq c) L (zeros kk) []
    | (w, e) :: ys => implied G (aadd e (aconst (-1))) && zhalt fuel (cq c) L w []
    end
  | R =>
    match cr c with
    | [] => zhalt fuel (cq c) R [] (zeros kk)
    | (w, e) :: ys => implied G (aadd e (aconst (-1))) && zhalt fuel (cq c) R [] w
    end
  end.

Theorem halt_stage c G : Reach c G -> halt_final2 G c = true -> halts tm c0.
Proof.
  intros [rho [HG Hg]] Hf.
  assert (Hend : exists c', den rho (const S0) (const S0) c -[ tm ]->* c' /\ halted tm c').
  { unfold halt_final2 in Hf. unfold den. destruct c as [q d ls rs]. cbn [cq cd cl cr] in Hf |- *.
    destruct d.
    - destruct ls as [| [w e] ys].
      + cbn [sden]. pose proof (zhalt_spec fuel q L (zeros kk) [] (const S0) (sden rho rs (const S0)) Hf) as Hz.
        rewrite zeros_word in Hz. exact Hz.
      + apply andb_prop in Hf. destruct Hf as [H1 H2]. apply (implied_spec rho G) in H1; [| exact HG].
        rewrite aeval_aadd, aeval_aconst in H1. rewrite (dec1_spec rho w e ys (const S0)) by lia.
        exact (zhalt_spec fuel q L w [] _ _ H2).
    - destruct rs as [| [w e] ys].
      + cbn [sden]. pose proof (zhalt_spec fuel q R [] (zeros kk) (sden rho ls (const S0)) (const S0) Hf) as Hz.
        rewrite zeros_word in Hz. exact Hz.
      + apply andb_prop in Hf. destruct Hf as [H1 H2]. apply (implied_spec rho G) in H1; [| exact HG].
        rewrite aeval_aadd, aeval_aconst in H1. rewrite (dec1_spec rho w e ys (const S0)) by lia.
        exact (zhalt_spec fuel q R [] w _ _ H2). }
  destruct Hend as [c' [H1 H2]].
  eapply halts_from_evstep; [eapply evstep_trans; [exact Hg | exact H1] | exact H2].
Qed.

End Top.

(* ---------- the table grows one rule at a time: the right side of a rule is what its actions produce ---------- *)
Lemma allvalid_empty tm : AllValid tm TLeaf.
Proof. intros i r H. discriminate H. Qed.

Lemma allvalid_set tm t p x : AllValid tm t -> Valid tm x -> AllValid tm (rset t p x).
Proof.
  intros HV Hx i r H. destruct (rget_rset _ _ _ _ _ H) as [E | E].
  - subst r. exact Hx.
  - exact (HV _ _ E).
Qed.

Record Spec := mkSpec { s_q : Q; s_d : dir; s_L : Stk; s_cL : bool; s_R : Stk; s_cR : bool; s_G : list Aff; s_rep : bool; s_dy : list Z }.

Definition spec_rule (s : Spec) (c' : Cfg) : Rule :=
  mkRule (s_q s) (s_d s) (s_L s) (s_cL s) (s_R s) (s_cR s) (s_G s) (cq c') (cd c') (cl c') (cr c') (s_rep s) (s_dy s).

Definition spec_start (s : Spec) : Cfg := mkC (s_q s) (s_d s) (s_L s) (s_R s).

Lemma spec_rule_valid tm kk fuel rules s a acts c' :
  AllValid tm rules ->
  exec_acts tm kk fuel rules (s_G s) (s_cL s) (s_cR s) (a :: acts) (spec_start s) = Some c' ->
  Valid tm (spec_rule s c').
Proof.
  intros HV E rho HG tl tr HL HR. destruct c' as [q1 d1 l1 r1].
  exact (exec_acts_plus tm kk fuel rules rho (s_G s) (s_cL s) (s_cR s) tl tr a acts _ _ HV HG HL HR E).
Qed.

(* A compact encoding of certificates as an array of 63-bit integers.
   The decoder is not trusted: everything it produces goes through the checker above. *)
From Coq Require Import ZArith List PArray PrimInt63 PrimString.
From Coq Require Uint63.
Import ListNotations.
Set Default Goal Selector "!".

Local Open Scope Z_scope.

(* a state of the reader: index into the expanded data *)
Definition St : Type := int.

Definition small : array Z := SkInts.small.

(* the value of one element, 5 bits at a time *)
Fixpoint zof (fuel : nat) (e : int) (v sh : Z) : Z :=
  match fuel with
  | O => v
  | S f =>
    if PrimInt63.eqb e SkInts.i0 then v
    else zof f (PrimInt63.lsr e SkInts.i5) (v + PArray.get small (PrimInt63.land e SkInts.i31) * sh) (sh * 32)
  end.

(* bit 62 of an element says that more elements of this number follow; each of those holds 60 bits *)
Fixpoint rdu (d : array int) (fuel : nat) (v sh : Z) (s : St) : Z * St :=
  match fuel with
  | O => (v, s)
  | S fuel' =>
    let e := PArray.get d s in
    let s1 := PrimInt63.add s SkInts.i1 in
    if PrimInt63.ltb e SkInts.flag then (zof 13 e v sh, s1)
    else rdu d fuel' (zof 13 (PrimInt63.land e SkInts.mask60) v sh) (sh * 1152921504606846976) s1
  end.

Definition rdn (d : array int) (s : St) : Z * St := rdu d 100 0 1 s.

Definition zig (v : Z) : Z := if Z.even v then Z.div v 2 else - Z.div (v + 1) 2.

Definition rdz (d : array int) (s : St) : Z * St := let (v, s1) := rdn d s in (zig v, s1).

Definition rdnat (d : array int) (s : St) : nat * St := let (v, s1) := rdn d s in (Z.to_nat v, s1).

Fixpoint rdlist {A : Type} (f : St -> A * St) (n : nat) (s : St) : list A * St :=
  match n with
  | O => ([], s)
  | S n' =>
    let (x, s1) := f s in
    let (t, s2) := rdlist f n' s1 in
    (x :: t, s2)
  end.

Definition rdcount (d : array int) {A : Type} (f : St -> A * St) (s : St) : list A * St :=
  let (n, s1) := rdnat d s in rdlist f n s1.

Definition rdterm (d : array int) (s : St) : (nat * Z) * St :=
  let (v, s1) := rdnat d s in let (a, s2) := rdz d s1 in ((v, a), s2).

Definition rdaff (d : array int) (s : St) : Aff * St :=
  let (c, s1) := rdz d s in let (t, s2) := rdcount d (rdterm d) s1 in ((c, t), s2).

Definition qofn (n : Z) : Q :=
  match n with 0 => A | 1 => B | 2 => C | 3 => D | 4 => E | _ => F end.

(* one window entry: token = word * 4 + tag; tag 0: count is the next variable; 1: a constant follows; 2: modulus and residue follow *)
Definition rdentry (d : array int) (words : array (list Sym)) (st : (nat * St)) : (list Sym * Aff) * (nat * St) :=
  let (nv, s) := st in
  let (t, s1) := rdn d s in
  let tag := Z.modulo t 4 in
  let w := PArray.get words (Uint63.of_Z (Z.div t 4)) in
  if Z.eqb tag 0 then ((w, (0, [(nv, 1)])), (S nv, s1))
  else if Z.eqb tag 1 then
    let (c, s2) := rdn d s1 in ((w, (c, [])), (nv, s2))
  else
    let (m, s2) := rdn d s1 in
    let (r, s3) := rdn d s2 in
    ((w, (r, [(nv, m)])), (S nv, s3)).

Fixpoint rdentries (d : array int) (words : array (list Sym)) (n : nat) (st : nat * St) : list (list Sym * Aff) * (nat * St) :=
  match n with
  | O => ([], st)
  | S n' =>
    let (x, st1) := rdentry d words st in
    let (t, st2) := rdentries d words n' st1 in
    (x :: t, st2)
  end.

(* a guard: token = v * 2 for a single variable with coefficient 1, then the bound; else nterms * 2 + 1, the terms, then the bound *)
Definition rdguard (d : array int) (s : St) : Aff * St :=
  let (t, s1) := rdn d s in
  if Z.even t then
    let (m, s2) := rdz d s1 in ((- m, [(Z.to_nat (Z.div t 2), 1)]), s2)
  else
    let (ts, s2) := rdlist (rdterm d) (Z.to_nat (Z.div t 2)) s1 in
    let (m, s3) := rdz d s2 in ((- m, ts), s3).

(* an action: token = n * 4 + tag; tag 0: AS; 1: AR; 2: ARK and an affine k follows *)
Definition rdact (d : array int) (s : St) : Act * St :=
  let (t, s1) := rdn d s in
  let tag := Z.modulo t 4 in
  let n := Z.div t 4 in
  if Z.eqb tag 0 then (AS (Z.to_pos n), s1)
  else if Z.eqb tag 1 then (AR (Z.to_pos (n + 1)), s1)
  else let (k, s2) := rdaff d s1 in (ARK (Z.to_pos (n + 1)) k, s2).

(* the head of a rule; its actions follow in the data and are read one at a time while they run *)
Definition rdhead (d : array int) (words : array (list Sym)) (s : St) : Spec * St :=
  let (h, s1) := rdn d s in
  (* h = q * 8 + dir * 4 + cL * 2 + cR, with rep in the next token *)
  let q := qofn (Z.div h 8) in
  let dr := if Z.eqb (Z.modulo (Z.div h 4) 2) 1 then R else L in
  let cL := Z.eqb (Z.modulo (Z.div h 2) 2) 1 in
  let cR := Z.eqb (Z.modulo h 2) 1 in
  let (nl, s2) := rdnat d s1 in
  let (Lw, st1) := rdentries d words nl (0%nat, s2) in
  let (nr, s3) := rdnat d (snd st1) in
  let (Rw, st2) := rdentries d words nr (fst st1, s3) in
  let nv := fst st2 in
  let s4 := snd st2 in
  let (G, s5) := rdcount d (rdguard d) s4 in
  let (rp, s6) := rdn d s5 in
  let (dy, s7) := if Z.eqb rp 1 then rdlist (rdz d) nv s6 else ([], s6) in
  (mkSpec q dr Lw cL Rw cR G (Z.eqb rp 1) dy, s7).

Definition rdpairz (d : array int) (s : St) : (Z * Z) * St :=
  let (a, s1) := rdz d s in let (b, s2) := rdz d s1 in ((a, b), s2).

Definition rdpairn (d : array int) (s : St) : (nat * Z) * St :=
  let (a, s1) := rdnat d s in let (b, s2) := rdz d s1 in ((a, b), s2).

Definition rdsx (d : array int) (s1 : St) : Stage * St :=
  let (i, s2) := rdn d s1 in
  let (sl, s3) := rdcount d (rdaff d) s2 in
  let (k, s4) := rdaff d s3 in
  let (Fm, s5) := rdcount d (rdpairz d) s4 in
  let (nvO, s6) := rdnat d s5 in
  let (Bd, s7) := rdcount d (rdpairn d) s6 in
  (SX (Z.to_pos (i + 1)) sl k Fm nvO Bd, s7).

Fixpoint tosym (w : int) (n : nat) : list Sym :=
  match n with
  | O => []
  | S n' =>
    (if PrimInt63.eqb (PrimInt63.land w SkInts.i1) SkInts.i1 then S1 else S0)
      :: tosym (PrimInt63.lsr w SkInts.i1) n'
  end.

Fixpoint words_sym_rec (w : array int) (kk : nat) (a : array (list Sym)) (n : nat) (i : int) : array (list Sym) :=
  match n with
  | O => a
  | S n' => words_sym_rec w kk (PArray.set a i (tosym (PArray.get w i) kk)) n' (PrimInt63.add i SkInts.i1)
  end.

Definition words_sym (w : array int) (kk n : nat) : array (list Sym) :=
  words_sym_rec w kk (PArray.make (PArray.length w) []) n SkInts.i0.

(* ---------- reading and checking go together: what was read and used becomes garbage.
   The readers are abstract here, so no proof below can depend on (or ever unfold) the decoder. ---------- *)
Section Stream.
Variables (rA : St -> Act * St) (rH : St -> Spec * St) (rN : St -> nat * St) (rT : St -> Z * St) (rX : St -> Stage * St).

Fixpoint exec_stream tm kk fuel rules (G : list Aff) (cL cR : bool) (n : nat) (c : Cfg) (s : St) : option (Cfg * St) :=
  match n with
  | O => Some (c, s)
  | S n' =>
    let (a, s1) := rA s in
    match exec_act tm kk fuel rules G cL cR a c with
    | Some c1 => exec_stream tm kk fuel rules G cL cR n' c1 s1
    | None => None
    end
  end.

Lemma exec_stream_acts tm kk fuel rules G cL cR n c s c' s' :
  exec_stream tm kk fuel rules G cL cR n c s = Some (c', s') ->
  exists acts, List.length acts = n /\ exec_acts tm kk fuel rules G cL cR acts c = Some c'.
Proof.
  revert c s. induction n as [| n IH]; intros c s H; cbn [exec_stream] in H.
  - inversion H; subst. exists (@nil Act). split; reflexivity.
  - destruct (rA s) as [a s1]. cbv beta iota in H.
    destruct (exec_act tm kk fuel rules G cL cR a c) as [c1 |] eqn:E; [| discriminate].
    destruct (IH _ _ H) as [t [Ht Hx]]. exists (a :: t). split.
    + cbn [List.length]. rewrite Ht. reflexivity.
    + cbn [exec_acts]. rewrite E. exact Hx.
Qed.

Fixpoint stream_rules tm kk fuel (n : nat) (done : RT) (id : positive) (s : St) : option (RT * St) :=
  match n with
  | O => Some (done, s)
  | S n' =>
    let (sp, s1) := rH s in
    let (m, s2) := rN s1 in
    match m with
    | O => None
    | S _ =>
      match exec_stream tm kk fuel done (s_G sp) (s_cL sp) (s_cR sp) m (spec_start sp) s2 with
      | Some (c', s3) => stream_rules tm kk fuel n' (rset done id (spec_rule sp c')) (Pos.succ id) s3
      | None => None
      end
    end
  end.

Lemma stream_rules_spec tm kk fuel n done id s rs s' :
  AllValid tm done -> stream_rules tm kk fuel n done id s = Some (rs, s') -> AllValid tm rs.
Proof.
  revert done id s. induction n as [| n IH]; intros done id s HV H; cbn [stream_rules] in H.
  - inversion H; subst. exact HV.
  - destruct (rH s) as [sp s1]. cbv beta iota in H.
    destruct (rN s1) as [m s2]. cbv beta iota in H.
    destruct m as [| m']; [discriminate |].
    destruct (exec_stream tm kk fuel done (s_G sp) (s_cL sp) (s_cR sp) (S m') (spec_start sp) s2) as [[c' s3] |] eqn:E; [| discriminate].
    destruct (exec_stream_acts _ _ _ _ _ _ _ _ _ _ _ _ E) as [acts [Hl Ha]].
    destruct acts as [| a t]; [discriminate |].
    exact (IH _ _ _ (allvalid_set _ _ _ _ HV (spec_rule_valid _ _ _ _ _ _ _ _ HV Ha)) H).
Qed.

Fixpoint stream_stages tm kk fuel rs (n : nat) (Sx : Cfg) (G : list Aff) (s : St) : option (Cfg * list Aff * St) :=
  match n with
  | O => Some (Sx, G, s)
  | S n' =>
    let (t, s1) := rT s in
    if Z.eqb t 0 then
      let (m, s2) := rN s1 in
      match exec_stream tm kk fuel rs G true true m Sx s2 with
      | Some (Sy, s3) => stream_stages tm kk fuel rs n' Sy G s3
      | None => None
      end
    else
      let (st, s2) := rX s1 in
      match run_stages tm kk fuel rs [st] Sx G with
      | Some (Sy, Gy) => stream_stages tm kk fuel rs n' Sy Gy s2
      | None => None
      end
  end.

Lemma stream_stages_spec tm kk fuel rs n Sx G s Sy Gy s' :
  AllValid tm rs -> Reach tm Sx G ->
  stream_stages tm kk fuel rs n Sx G s = Some (Sy, Gy, s') -> Reach tm Sy Gy.
Proof.
  intros HV. revert Sx G s. induction n as [| n IH]; intros Sx G s HR H; cbn [stream_stages] in H.
  - inversion H; subst. exact HR.
  - destruct (rT s) as [t s1]. cbv beta iota in H.
    destruct (Z.eqb t 0).
    + destruct (rN s1) as [m s2]. cbv beta iota in H.
      destruct (exec_stream tm kk fuel rs G true true m Sx s2) as [[Sz s3] |] eqn:E; [| discriminate].
      destruct (exec_stream_acts _ _ _ _ _ _ _ _ _ _ _ _ E) as [acts [_ Ha]].
      exact (IH _ _ _ (reach_exec tm kk fuel rs HV _ _ _ _ HR Ha) H).
    + destruct (rX s1) as [st s2]. cbv beta iota in H.
      destruct (run_stages tm kk fuel rs [st] Sx G) as [[Sz Gz] |] eqn:E; [| discriminate].
      exact (IH _ _ _ (run_stages_spec tm kk fuel rs HV _ _ _ _ _ HR E) H).
Qed.

Definition halt_stream tm kk fuel (s0 : St) : bool :=
  let (ns, s1) := rN s0 in
  match stream_rules tm kk fuel ns TLeaf 1%positive s1 with
  | None => false
  | Some (rs, s2) =>
    let (n, s3) := rN s2 in
    match stream_stages tm kk fuel rs n start [] s3 with
    | Some (Sx, Gx, _) => halt_final2 tm kk fuel Gx Sx
    | None => false
    end
  end.

Theorem halt_stream_spec tm kk fuel s0 : halt_stream tm kk fuel s0 = true -> halts tm c0.
Proof.
  unfold halt_stream. destruct (rN s0) as [ns s1]. cbv beta iota.
  destruct (stream_rules tm kk fuel ns TLeaf 1%positive s1) as [[rs s2] |] eqn:E1; [| discriminate].
  pose proof (stream_rules_spec _ _ _ _ _ _ _ _ _ (allvalid_empty tm) E1) as HV.
  destruct (rN s2) as [n s3]. cbv beta iota.
  destruct (stream_stages tm kk fuel rs n start [] s3) as [[[Sx Gx] s4] |] eqn:E2; [| discriminate].
  intros H. exact (halt_stage _ _ _ _ _ (stream_stages_spec _ _ _ _ _ _ _ _ _ _ _ HV (reach_start tm) E2) H).
Qed.

Variable (rL : St -> list Aff * St).

Definition cycle_stream tm kk fuel (i nv : nat) (s0 : St) : bool :=
  let (ns, s1) := rN s0 in
  match stream_rules tm kk fuel ns TLeaf 1%positive s1 with
  | None => false
  | Some (rs, s2) =>
    let (n, s3) := rN s2 in
    match stream_stages tm kk fuel rs n start [] s3 with
    | Some (Sx, Gx, s4) =>
      let (fl, s5) := rL s4 in
      let (sl, _) := rL s5 in
      match rget rs (Pos.of_succ_nat i) with
      | Some r => cycle_ok2 Gx r nv (fun j => nth j fl (0%Z, [])) (fun j => nth j sl (0%Z, [])) Sx
      | None => false
      end
    | None => false
    end
  end.

Theorem cycle_stream_spec tm kk fuel i nv s0 : cycle_stream tm kk fuel i nv s0 = true -> ~ halts tm c0.
Proof.
  unfold cycle_stream. destruct (rN s0) as [ns s1]. cbv beta iota.
  destruct (stream_rules tm kk fuel ns TLeaf 1%positive s1) as [[rs s2] |] eqn:E1; [| discriminate].
  pose proof (stream_rules_spec _ _ _ _ _ _ _ _ _ (allvalid_empty tm) E1) as HV.
  destruct (rN s2) as [n s3]. cbv beta iota.
  destruct (stream_stages tm kk fuel rs n start [] s3) as [[[Sx Gx] s4] |] eqn:E2; [| discriminate].
  destruct (rL s4) as [fl s5]. cbv beta iota.
  destruct (rL s5) as [sl s6]. cbv beta iota.
  destruct (rget rs (Pos.of_succ_nat i)) as [r |] eqn:Er; [| discriminate].
  intros H. exact (cycle_stage tm _ _ _ _ _ _ (stream_stages_spec _ _ _ _ _ _ _ _ _ _ _ HV (reach_start tm) E2) (HV _ _ Er) H).
Qed.
End Stream.

Definition s00 : St := SkInts.i0.

Definition halt_data tm kk fuel d words : bool :=
  halt_stream (rdact d) (rdhead d words) (rdnat d) (rdn d) (rdsx d) tm kk fuel s00.

Theorem halt_data_spec tm kk fuel d words : halt_data tm kk fuel d words = true -> halts tm c0.
Proof. exact (halt_stream_spec (rdact d) (rdhead d words) (rdnat d) (rdn d) (rdsx d) tm kk fuel s00). Qed.

Definition cycle_data tm kk fuel d words (i nv : nat) : bool :=
  cycle_stream (rdact d) (rdhead d words) (rdnat d) (rdn d) (rdsx d) (rdcount d (rdaff d)) tm kk fuel i nv s00.

Theorem cycle_data_spec tm kk fuel d words i nv : cycle_data tm kk fuel d words i nv = true -> ~ halts tm c0.
Proof. exact (cycle_stream_spec (rdact d) (rdhead d words) (rdnat d) (rdn d) (rdsx d) (rdcount d (rdaff d)) tm kk fuel i nv s00). Qed.

(* ---------- the data as written in a file: one primitive string, LZ-compressed; also untrusted ----------
   A character is a 6-bit group plus 48. A number is a little-endian varint of groups (5 bits, bit 5 = more).
   An item is x: x even: x/2 literal numbers follow; x odd: copy x/2 numbers from the distance that follows. *)
Section Expand.
Variable c : PrimString.string.

Definition cg (i : int) : int := PrimInt63.sub (PrimString.get c i) SkInts.i48.

Fixpoint rdv (fuel : nat) (v sh i : int) : int * int :=
  match fuel with
  | O => (v, i)
  | S f =>
    let g := cg i in
    let i' := PrimInt63.add i SkInts.i1 in
    if PrimInt63.ltb g SkInts.i32 then (PrimInt63.lor v (PrimInt63.lsl g sh), i')
    else rdv f (PrimInt63.lor v (PrimInt63.lsl (PrimInt63.land g SkInts.i31) sh)) (PrimInt63.add sh SkInts.i5) i'
  end.

Definition rd1 (i : int) : int * int := rdv 14 SkInts.i0 SkInts.i0 i.

(* f applied n times *)
Fixpoint iter {T : Type} (f : T -> T) (fuel : nat) (n : int) (x : T) : T :=
  match fuel with
  | O => x
  | S k =>
    if PrimInt63.eqb n SkInts.i0 then x
    else
      let h := PrimInt63.lsr n SkInts.i1 in
      let y := iter f k h (iter f k h x) in
      if PrimInt63.eqb (PrimInt63.land n SkInts.i1) SkInts.i1 then f y else y
  end.

Definition xlit (st : array int * int * int) : array int * int * int :=
  let '(a, n, i) := st in
  let (v, i') := rd1 i in
  (PArray.set a n v, PrimInt63.add n SkInts.i1, i').

Definition xcopy (dist : int) (st : array int * int) : array int * int :=
  let (a, n) := st in
  (PArray.set a n (PArray.get a (PrimInt63.sub n dist)), PrimInt63.add n SkInts.i1).

Definition xitem (st : array int * int * int) : array int * int * int :=
  let '(a, n, i) := st in
  let (x, i2) := rd1 i in
  let m := PrimInt63.lsr x SkInts.i1 in
  if PrimInt63.eqb (PrimInt63.land x SkInts.i1) SkInts.i0 then iter xlit 63 m (a, n, i2)
  else
    let (dist, i3) := rd1 i2 in
    let (a2, n2) := iter (xcopy dist) 63 m (a, n) in
    (a2, n2, i3).

Definition expand (nitems ntok : int) : array int :=
  let '(a, _, _) := iter xitem 63 nitems (PArray.make ntok SkInts.i0, SkInts.i0, SkInts.i0) in a.
End Expand.

(* ---------- the certificate; not trusted ---------- *)
Module Dat.
Definition wn : int := 124%uint63.
Definition wstr : PrimString.string := "h7ko2Zo2cA[e3bAke3SIne2RIoe2bIbY1VS1Vc1XV3ng2jg2\V2^m3Zm3\T3_e2ZT3ke2X>XV1a\2^e2i<^o2km3o[1m[1gn1en1iX2gZ3hX2Tc1Tc2m_1e_1kg2gj3ej3oZ1Tb1Vb1mj3a<i\2ne3cIaL^e3mn1bS1VU3\V3XV2^V2TW2YImZ3ZV2YV3TU3\:lX2iD[o2g_1YAUS1cb1Ub1WS1Wc1TS1VU2^T3XZ2Ri1dX2\Z2l<Uc1cR1Wb1bb1oj3oj2:iIaDd<d\2ZV3TW3m[3ee2fZ3g:jZ1iAbc1`\2kj3Tc3\T1]e2_EQIne1_]1[[1gf2_m3bU3j_112Vb2\V1"%pstring.
